window.IMGUI_DOCS.guides.push(...[{"id":"engine-editor-architecture","category":"engine","level":"intermediate","minutes":18,"title":"自作エンジンの最初の一歩：UIとゲームの仕事を分けよう","summary":"Hierarchy、Inspector、Sceneビュー。まずは3枚のパネルが同じデータを見られる、小さなエディターから始めてみましょう。","related_api":["ImGui::Begin","ImGui::End","ImGui::Selectable","ImGui::DragFloat3","ImGui::Button"],"related_guides":["frame-state","frame-integration","engine-hierarchy-ids","engine-undo-redo"],"tags":["ゲームエンジン","エディター設計","状態管理"],"sections":[{"title":"ImGuiが担当するのは、エンジンを操作する画面","paragraphs":["Hierarchyで物体を選び、Inspectorで位置を変えると、Sceneにも同じ変更が出る。まずはこの一往復を、小さなエディターの目標にしましょう。","三つのパネルは、同じアプリのデータを参照します。パネルごとに位置のコピーを持つと、片方を編集しても他方へ反映されなくなります。選択中の物体と編集先を、共通のモデルへ集めます。","Dear ImGuiは、ボタンや入力欄を使った操作画面を担当します。3D描画、ECS、物理、アセット管理はアプリ側で用意します。UIからどの処理を呼ぶかを決め、少しずつ接続していきます。"],"table":{"headers":["役割","持っておくデータ","担当する処理"],"rows":[["エンジンモデル","物体・Transform・アセットID","シミュレーション・描画・保存"],["エディター状態","選択ID・開いているパネル","選択・表示モード・履歴"],["ImGuiの呼び出し","モデルへの参照","入力欄と操作結果の受け渡し"]]},"id":"engine-editor-architecture-section-1"},{"title":"3つのパネルから、1つのモデルを触ってみる","paragraphs":["次の関数はNewFrame()とRender()の間で毎フレーム呼びます。モデルは呼び出し元が保持してください。ここでのdirtyは「未保存の変更がある」というアプリ側の印です。"],"code":"#include \"imgui.h\"\n    struct EditorModel\n    {\n        bool selected = true;\n        bool dirty = false;\n        float position[3] = {0.0f, 0.0f, 0.0f};\n    };\n    void DrawSmallEditor(EditorModel & model)\n    {\n        if (ImGui::Begin(\"Hierarchy\"))\n        {\n            if (ImGui::Selectable(\"Cube\", model.selected))\n                model.selected = !model.selected;\n        }\n        ImGui::End();\n        if (ImGui::Begin(\"Inspector\") && model.selected)\n        {\n            if (ImGui::DragFloat3(\"Position\", model.position, 0.05f))\n                model.dirty = true;\n        }\n        ImGui::End();\n        if (ImGui::Begin(\"Scene\"))\n        {\n            ImGui::Text(\"Cube: %.2f, %.2f, %.2f\",\n                model.position[0],\n                model.position[1],\n                model.position[2]);\n            ImGui::TextUnformatted(model.dirty ? \"Unsaved changes\" : \"Saved\");\n        }\n        ImGui::End();\n    }","id":"engine-editor-architecture-section-2","capture":{"guide_id":"engine-editor-architecture","section_index":1,"scene":"example-engine-editor-architecture-02","mode":"direct","caption":"掲載コードを実行した表示です。","backend":"DirectX 11 / WARP","code_sha256":"dd26c9148df7112e2ec9553c2c6a3411a8166a0fd440878371d7d1d53efaeedb","image_sha256":"27a65f7b427276d44e173895f6f9945050e3344a5c220e09a7aeeab298a8f1f6","fixture":"static EditorModel model; DrawSmallEditor(model);","initialization":""}},{"title":"変更すると困る処理は、いったん要求として集める","paragraphs":["名前の編集程度ならその場で値を書き換えても始められます。一方、物体の削除やシーン切り替えは、他のパネルが参照している途中に実行すると危険です。**UIでは要求を積み、全パネルを描き終えてから反映する**形にすると扱いやすくなります。","次はキューの最小モデルです。ボタンは削除要求を追加するだけで、実際の反映は呼び出し元がUI処理の後に行います。Undoを付けるときも、この変更の入口を活用できます。"],"code":"#include \"imgui.h\"\n#include <vector>\n    enum class EditKind\n    {\n        DeleteObject,\n        ResetPosition\n    };\n    struct EditRequest\n    {\n        EditKind kind;\n        int entity_id;\n    };\n    struct ObjectModel\n    {\n        int id = 1;\n        bool alive = true;\n        float x = 2.0f;\n    };\n    void DrawObjectActions(int selected_id, std::vector<EditRequest>& requests)\n    {\n        if (ImGui::Button(\"Delete\"))\n            requests.push_back({EditKind::DeleteObject, selected_id});\n        ImGui::SameLine();\n        if (ImGui::Button(\"Reset position\"))\n            requests.push_back({EditKind::ResetPosition, selected_id});\n    }\n    void ApplyRequests(\n        ObjectModel & object, std::vector<EditRequest> & requests)\n    {\n        for (const EditRequest& request : requests)\n        {\n            if (!object.alive || request.entity_id != object.id)\n                continue;\n            if (request.kind == EditKind::DeleteObject)\n                object.alive = false;\n            else\n                object.x = 0.0f;\n        }\n        requests.clear();\n    }","id":"engine-editor-architecture-section-3","capture":{"guide_id":"engine-editor-architecture","section_index":2,"scene":"example-engine-editor-architecture-03","mode":"direct","caption":"掲載コードを実行した表示です。","backend":"DirectX 11 / WARP","code_sha256":"3dace9c296bdde6c12db9eb46ddd4104b3002ad569a8f4119aa23503e1f4c119","image_sha256":"7c0afed8ba989cec7a3ae46b0d7757caa2a38d3fe70d1c1e4032b60d640bb5c7","fixture":"static ObjectModel model; static std::vector<EditRequest> requests; DrawObjectActions(1, requests); ApplyRequests(model, requests); ImGui::Text(\"Pending requests: %zu\", requests.size());","initialization":""}},{"title":"フレームの順番を決めておこう","paragraphs":["最初は「イベントを読む → ImGuiのNewFrame → パネルを作る → 編集要求を反映 → エンジン更新 → シーンとUIを描画」という流れを紙に書いておくと、値がいつ変わるか追いやすくなります。既存エンジンが別の更新順なら、どの時点の状態をUIに見せるかを明示しましょう。","Render()はImGuiの描画データをまとめる処理です。シーンの描画やGPUへの送信、Presentまで自動で行う処理ではありません。Sceneパネルに3D画像を出す段階では、アプリのレンダラーが作ったテクスチャをImage()へ渡します。"],"id":"engine-editor-architecture-section-4"},{"title":"小さく動いたら、次に何を足す？","paragraphs":["次は選択をboolから安定したEntity IDへ変えてみましょう。名前変更、並べ替え、削除をしても選択が別の物体へ飛ばないことを確かめると、エディターの土台がぐっと丈夫になります。"],"bullets":["最初から全コンポーネントを自動表示しようとせず、Transformひとつで編集の流れを完成させましょう。","UI内のstaticは試作に便利ですが、複数プロジェクトや複数シーンではエディター状態を明示的なオブジェクトにまとめると混ざりません。","レイアウトの自由な配置はDockingブランチへ進んでから追加できます。"],"id":"engine-editor-architecture-section-5"},{"title":"App・Editor・Rendererのつながり","paragraphs":["Appがシーンと設定を保持し、Editorが選択中の値を編集し、Rendererがその結果から画像を作ります。画像用テクスチャの寿命は、ImGuiが描画し終わるまで保ちましょう。実アプリでは画像を当フレーム/前フレームのどちらで見せるかも描画順と合わせて決めます。"],"flow":["App：シーン・選択ID・Undoを保持","Editor：NewFrameの後、保持データを読み書き","Renderer：3D画像をレンダーターゲットへ描く","UI描画：Imageで参照 → Render/GetDrawData → GPUへ提出"],"id":"engine-editor-architecture-section-6"}],"sources":[{"title":"Dear ImGui v1.93.0: 公開APIと各関数の契約","url":"https://github.com/ocornut/imgui/blob/v1.93.0/imgui.h"},{"title":"公式FAQ: ID・入力・アプリとの役割分担","url":"https://github.com/ocornut/imgui/blob/v1.93.0/docs/FAQ.md"},{"title":"自作エンジン作者の開発記録: エディターと実行系の構成","url":"https://hanion.dev/post/enik-engine/"}],"image":"guide-engine-workbench","image_scene":"example-engine-editor-architecture-02","image_caption":"","reading":{"goal":"複数のパネルから、同じデータを読み書きできる。","when":"小さな自作エディターの構成を決めるとき","question":"Inspectorで位置を変えてもSceneへ反映されません。最初に何を確かめますか？","answer":"パネルごとに位置のコピーを持っていないか確認します。同じモデルを参照し、変更する時点もそろえます。"}},{"id":"engine-hierarchy-ids","category":"engine","level":"intermediate","minutes":20,"title":"Hierarchyを作ろう：名前が変わっても選択を保つID設計","summary":"同じ名前のCubeが並んでも大丈夫。表示名、物体のID、ImGuiのIDを分けて、選択が迷子にならない一覧を作ります。","related_api":["ImGui::PushID","ImGui::PopID","ImGui::TreeNodeEx","ImGui::TreePop","ImGui::IsItemClicked","ImGui::IsItemToggledOpen"],"related_guides":["id-stack","labels-hash","engine-safe-deletion","engine-transform-inspector","visual-marquee","engine-parent-change","engine-multi-inspector"],"tags":["Hierarchy","Entity ID","選択","ツリー"],"sections":[{"title":"名前や配列の位置を、物体の正体にしない","paragraphs":["Hierarchyを名前順に並べ替えたら、選択が別の物体へ移ってしまった。この問題は、行番号を物体の識別に使っていると起こります。選択状態には、物体ごとに変わらないIDを保存します。","表示名は変更でき、同じ名前の物体も置けます。ImGuiのIDはUI状態の識別、Entity IDはアプリの物体の識別です。役割を分け、UIを描くときに対象のIDを渡します。","下の例は、0を未選択とする正のint IDです。実際のECSが64bit IDや世代付きハンドルなら、その体系を保ちます。PushID(int)へ切り詰めると衝突するので、完全なIDを文字列へ変換するなどの方法を選びます。"],"id":"engine-hierarchy-ids-section-1"},{"title":"まずは安定IDを使った平らな一覧から","paragraphs":["この関数は有効なImGuiウィンドウ内で呼びます。PushIDで物体ごとの名前空間を作り、ラベルの###以降を固定すると、表示名が変わっても同じUI項目として扱えます。PushIDだけでなく、Selectable自身のラベルIDも固定するのがポイントです。"],"code":"#include \"imgui.h\"\n#include <string>\n#include <vector>\n    struct EntityRow\n    {\n        int id;\n        std::string name;\n    };\n    void DrawEntityList(\n        const std::vector<EntityRow>& entities, int& selected_id)\n    {\n        for (const EntityRow& entity : entities)\n        {\n            ImGui::PushID(entity.id);\n            const std::string label = entity.name + \"###entity\";\n            if (ImGui::Selectable(label.c_str(), selected_id == entity.id))\n                selected_id = entity.id;\n            ImGui::PopID();\n        }\n    }","id":"engine-hierarchy-ids-section-2","capture":{"guide_id":"engine-hierarchy-ids","section_index":1,"scene":"example-engine-hierarchy-ids-02","mode":"direct","caption":"掲載コードを実行した表示です。","backend":"DirectX 11 / WARP","code_sha256":"a9d25a7b28753566518e37ac78530be5bb8367219a0e75923a5d1c18aa5c1c15","image_sha256":"76d94c354c4486266114f35dc775405e6cf741b1da705bc5de7959ea6d5ffe34","fixture":"static std::vector<EntityRow> rows{{101,\"Camera\"},{205,\"Player\"},{310,\"Ground\"}}; static int selected = 205; DrawEntityList(rows, selected); ImGui::Text(\"Selected entity: %d\", selected);","initialization":""}},{"title":"親子ツリーでも、選択はIDで受け渡す","paragraphs":["TreeNodeEx()がtrueなら、そのノードが開いた状態です。下の例は葉にもNoTreePushOnOpenを付けず、trueのとき必ずTreePop()する書き方に揃えています。","循環のない親子構造を前提にしています。ドラッグで親を付け替える処理では、自分自身や自分の子孫を親にできないよう、エンジン側で検証が必要です。"],"code":"#include \"imgui.h\"\n#include <string>\n#include <vector>\n    struct TreeEntity\n    {\n        int id;\n        std::string name;\n        std::vector<TreeEntity> children;\n    };\n    void DrawHierarchyNode(const TreeEntity& entity, int& selected_id)\n    {\n        ImGui::PushID(entity.id);\n        ImGuiTreeNodeFlags flags =\n            ImGuiTreeNodeFlags_OpenOnArrow | ImGuiTreeNodeFlags_SpanAvailWidth;\n        if (selected_id == entity.id)\n            flags |= ImGuiTreeNodeFlags_Selected;\n        if (entity.children.empty())\n            flags |= ImGuiTreeNodeFlags_Leaf;\n        const bool open =\n            ImGui::TreeNodeEx(\"node\", flags, \"%s\", entity.name.c_str());\n        if (ImGui::IsItemClicked() && !ImGui::IsItemToggledOpen())\n            selected_id = entity.id;\n        if (open)\n        {\n            for (const TreeEntity& child : entity.children)\n                DrawHierarchyNode(child, selected_id);\n            ImGui::TreePop();\n        }\n        ImGui::PopID();\n    }","id":"engine-hierarchy-ids-section-3","capture":{"guide_id":"engine-hierarchy-ids","section_index":2,"scene":"example-engine-hierarchy-ids-03","mode":"direct","caption":"掲載コードを実行した表示です。","backend":"DirectX 11 / WARP","code_sha256":"a6d081653f215bedc6c0a42226014d3abd998add0b8a563189b6a8308eb59469","image_sha256":"1fa278d39e82ed0ab6361ce00c3530e9a7bb2e177c271a4adbc90b7f4c501a00","fixture":"static TreeEntity root{1,\"World\",{{101,\"Camera\",{}},{205,\"Player\",{{206,\"Weapon\",{}}}},{310,\"Ground\",{}}}}; static int selected=205; ImGui::SetNextItemOpen(true, ImGuiCond_Always); DrawHierarchyNode(root,selected); ImGui::Text(\"Selected entity: %d\",selected);","initialization":""}},{"title":"親を移動すると、UIのパスも変わる","paragraphs":["上の再帰では祖先ノードもImGuiのIDスタックに入るため、親を付け替えるとその子のUI IDは変わります。**Entity IDによる選択は残っても、ツリーの開閉状態は別**です。親をまたぐ移動でも開閉を保ちたいなら、開閉状態もアプリ側のEntity IDで管理し、SetNextItemOpen()で反映する設計へ進めます。","物体のアドレスをPushIDへ渡す方法は、そのアドレスが変わらない間だけ安定します。vectorの再確保やコンポーネント移動があるエンジンでは、ポインターよりEntity IDを使う方が意図を説明しやすくなります。"],"id":"engine-hierarchy-ids-section-4"},{"title":"確認は「同じ名前を2つ置く」から","paragraphs":["Cubeを2個作り、片方を選択してから名前変更、並べ替え、親変更、削除を順に試しましょう。Inspectorが別のCubeを編集しないことと、削除後に未選択へ戻ることを確認します。"],"bullets":["表示名にはTextやTreeNodeExの書式引数として渡し、ユーザー入力をprintfの書式文字列にしないようにしましょう。","IDの再利用があるエンジンでは、番号だけでなく世代も含むハンドルを選択状態に持たせます。","大量ノードの描画を最適化する前に、安定IDと削除時の挙動を決めておくと後戻りが減ります。"],"id":"engine-hierarchy-ids-section-5"}],"sources":[{"title":"Dear ImGui v1.93.0: 公開APIと各関数の契約","url":"https://github.com/ocornut/imgui/blob/v1.93.0/imgui.h"},{"title":"公式FAQ: ID・入力・アプリとの役割分担","url":"https://github.com/ocornut/imgui/blob/v1.93.0/docs/FAQ.md"}],"image":"guide-engine-workbench","image_scene":"example-engine-hierarchy-ids-02","image_caption":"","reading":{"goal":"表示名や並び順が変わっても、同じ物体を選び続けられる。","when":"Hierarchyの選択が別の物体へずれるとき","question":"同名の物体を二つ置いた場合、名前だけで選択対象を保存できますか？","answer":"名前だけでは区別できません。安定した物体IDで保存し、表示名とUI内のIDの階層も分けて扱います。"}},{"id":"engine-transform-inspector","category":"engine","level":"intermediate","minutes":18,"title":"Transform Inspectorを育てよう：単位と編集ルールも伝える","summary":"位置・回転・拡大率を並べるだけでなく、「いま何を、どの単位で変えているのか」が分かるInspectorにしてみましょう。","related_api":["ImGui::DragFloat3","ImGui::SeparatorText","ImGui::BeginTable","ImGui::TableNextRow","ImGui::TableSetColumnIndex","ImGui::BeginDisabled"],"related_guides":["number-input","engine-hierarchy-ids","engine-undo-redo","engine-component-menu","engine-prefab-overrides"],"tags":["Inspector","Transform","単位","編集"],"sections":[{"title":"まずは値の意味をUIに出しておこう","paragraphs":["数値は変わったのに、思った向きへ回転しない。Inspectorを作るときは、部品を並べる前に、表示する座標系と単位を決めます。位置ならローカルかワールド、角度なら度かラジアンをラベルへ書きましょう。","例のTransformは、ローカル位置・度単位のオイラー角・拡大率を持つ説明用のモデルです。入力欄はこのデータを直接編集します。","クォータニオンを使うエンジンでは、表示用の角度との変換をアプリ側で用意します。クォータニオンの先頭3要素へ、そのままDragFloat3()をつなぐことはできません。"],"id":"engine-transform-inspector-section-1"},{"title":"3項目を、小さな部品としてまとめる","paragraphs":["戻り値は「どれかの値が今回変わったか」です。レンダラーへの通知やdirtyの更新は呼び出し元で行うと、UI部品がエンジンの詳細を抱えすぎずに済みます。"],"code":"#include \"imgui.h\"\n    struct LocalTransform\n    {\n        float position[3] = {0.0f, 0.0f, 0.0f};\n        float euler_degrees[3] = {0.0f, 0.0f, 0.0f};\n        float scale[3] = {1.0f, 1.0f, 1.0f};\n    };\n    bool DrawLocalTransform(LocalTransform & transform)\n    {\n        bool changed = false;\n        ImGui::SeparatorText(\"Local Transform\");\n        changed |= ImGui::DragFloat3(\"Position (m)\", transform.position, 0.01f);\n        changed |=\n            ImGui::DragFloat3(\"Rotation (deg)\", transform.euler_degrees, 0.5f);\n        changed |= ImGui::DragFloat3(\"Scale\",\n            transform.scale,\n            0.01f,\n            0.001f,\n            100.0f,\n            \"%.3f\",\n            ImGuiSliderFlags_AlwaysClamp);\n        return changed;\n    }","id":"engine-transform-inspector-section-2","capture":{"guide_id":"engine-transform-inspector","section_index":1,"scene":"example-engine-transform-inspector-02","mode":"direct","caption":"掲載コードを実行した表示です。","backend":"DirectX 11 / WARP","code_sha256":"0b844acf316040067f092f0c0600d584d884a1a75f31e79b3557ebfba15f187e","image_sha256":"17f43859ce4d889ac88ed698be00de93406683360c00af6b02c29923298c625c","fixture":"static LocalTransform value; DrawLocalTransform(value);","initialization":""}},{"title":"項目が増えたら、ラベルと値を2列へ","paragraphs":["数値欄の端が揃うと、コンポーネントが増えても目で追いやすくなります。次は同じTransform型を前提にしない、1つのfloat3を編集する独立した部品です。呼び出しごとに固有のidを渡します。"],"code":"#include \"imgui.h\"\n    bool DrawVectorProperty(\n        const char* id, const char* label, float value[3], bool editable)\n    {\n        bool changed = false;\n        ImGui::PushID(id);\n        if (ImGui::BeginTable(\"property\", 2, ImGuiTableFlags_SizingStretchProp))\n        {\n            ImGui::TableSetupColumn(\n                \"Name\", ImGuiTableColumnFlags_WidthFixed, 130.0f);\n            ImGui::TableSetupColumn(\n                \"Value\", ImGuiTableColumnFlags_WidthStretch);\n            ImGui::TableNextRow();\n            ImGui::TableSetColumnIndex(0);\n            ImGui::AlignTextToFramePadding();\n            ImGui::TextUnformatted(label);\n            ImGui::TableSetColumnIndex(1);\n            ImGui::SetNextItemWidth(-1.0f);\n            ImGui::BeginDisabled(!editable);\n            changed = ImGui::DragFloat3(\"##value\", value, 0.01f);\n            ImGui::EndDisabled();\n            ImGui::EndTable();\n        }\n        ImGui::PopID();\n        return changed;\n    }","id":"engine-transform-inspector-section-3","capture":{"guide_id":"engine-transform-inspector","section_index":2,"scene":"example-engine-transform-inspector-03","mode":"direct","caption":"掲載コードを実行した表示です。","backend":"DirectX 11 / WARP","code_sha256":"4318251e299fe7163341f0a738a21813518e1e1c22ad3c5af842ae0500eee5f3","image_sha256":"2ad876031c85931fdb15a1fa242c050cd1985e704d086471f95dd2168128386b","fixture":"static float value[3]={1.25f,2.0f,-3.0f}; DrawVectorProperty(\"position\",\"Position (m)\",value,true);","initialization":""}},{"title":"入力範囲は、エンジンのルールと合わせよう","paragraphs":["最初の例では拡大率を正の範囲へ制限しています。これはこのモデルでの方針で、負の拡大率による反転が必要なエンジンなら別の制約にしてください。ゼロ拡大率を許すと逆行列を作れない場合があるので、描画・物理側の仕様とも相談します。","ImGuiSliderFlags_AlwaysClampはCtrl+クリックで手入力するときも範囲へ収めるために付けています。それでも保存ファイルやスクリプトから不正値が入る可能性はあるため、**UIだけを唯一の検証場所にしない**ようにしましょう。"],"id":"engine-transform-inspector-section-4"},{"title":"選択変更と、編集中の値をどう扱う？","paragraphs":["別のEntityを選んだときは、そのEntityのTransformを毎フレーム渡します。選択前のポインターをInspectorが長く保持せず、IDから対象を解決する方が削除にも対応しやすくなります。","Undoを追加するときは、DragFloat3のtrueごとに履歴を作るのではなく、編集を始める直前の値を保持し、編集が終わったタイミングでひとつの操作として確定します。複数軸ウィジェットの扱いはUndoの記事で整理しましょう。","複数のEntityを切り替える実装では、Inspectorの呼び出し側をEntityの安定IDでPushID/PopIDして、別の対象へ同じ入力欄の編集中状態を持ち越さないようにします。選択を切り替える前に、未確定の編集を確定するか取り消すかも決めておきましょう。"],"id":"engine-transform-inspector-section-5"}],"sources":[{"title":"Dear ImGui v1.93.0: 公開APIと各関数の契約","url":"https://github.com/ocornut/imgui/blob/v1.93.0/imgui.h"},{"title":"公式FAQ: ID・入力・アプリとの役割分担","url":"https://github.com/ocornut/imgui/blob/v1.93.0/docs/FAQ.md"},{"title":"Cubos Team: Inspectorで型ごとの表示を拡張する実例","url":"https://cubos.riscadoa.com/blog/release-07/"}],"image":"guide-engine-workbench","image_scene":"example-engine-transform-inspector-02","image_caption":"","reading":{"goal":"位置・回転・拡縮の単位と編集先をそろえられる。","when":"TransformのInspectorを作るとき","question":"回転を数値で編集できました。エンジンへ渡す前に何を確認しますか？","answer":"度とラジアン、ローカルとワールドなどの規約を確認します。UIで見せる値とエンジンが持つ値の間で、必要な変換を行います。"}},{"id":"engine-viewport-picking","category":"engine","level":"advanced","minutes":25,"title":"Sceneビューをクリックして選択する：画像座標からピクセルへ","summary":"ゲーム画面をImageで表示したら、次はクリック位置をレンダーターゲットの座標へ変換してみましょう。余白・DPI・上下反転を順番に整理します。","related_api":["ImGui::Image","ImGui::GetItemRectMin","ImGui::GetItemRectMax","ImGui::IsItemHovered","ImGui::GetMousePos","ImGui::IsMouseClicked"],"related_guides":["image-texture","image-dx11","image-dx12","extensions-imguizmo","engine-input-focus","visual-pan-zoom","visual-atlas-viewer"],"tags":["Viewport","ピッキング","レンダーターゲット","座標変換"],"sections":[{"title":"SceneとGameは、同じ画像でなくてもいい","paragraphs":["Sceneビューの物体をクリックしても、少し離れた物体が選ばれる。まずは、表示した画像の中で何ピクセル目を押したかを正しく求めます。","Sceneは編集用カメラ、Gameはゲーム内カメラ、と画像を分けられます。ImGuiは、アプリが用意したそれぞれのテクスチャをImage()で表示します。","下の例が扱うのは、画像上のクリック位置から描画先のピクセル座標への変換です。その先の物体判定には、レイを飛ばす方法や、物体IDを描いた画像を読み戻す方法などをアプリ側で組み合わせます。"],"id":"engine-viewport-picking-section-1"},{"title":"ウィンドウ位置ではなく、Imageの四隅を基準にする","paragraphs":["次の関数は有効なウィンドウ内で呼びます。textureはアプリが作成した有効なテクスチャ参照、widthとheightは実際の描画先のピクセル数です。Imageの余白と枠を除くため、枠線の幅をこの呼び出し中だけ0にしています。","GetItemRectMin/Max()は必ずImage()の直後に読みます。間にText()を置くと「直前の項目」が変わってしまいます。uvを反転した場合は、ピッキングのvも同じ向きへ戻します。"],"code":"#include \"imgui.h\"\n#include <algorithm>\n#include <cmath>\n#include <optional>\n    struct PickPixel\n    {\n        int x;\n        int y;\n    };\n    std::optional<PickPixel> DrawSceneImage(\n        ImTextureRef texture, int width, int height, bool flip_y)\n    {\n        if (width <= 0 || height <= 0)\n            return std::nullopt;\n        const ImVec2 available = ImGui::GetContentRegionAvail();\n        if (available.x <= 0.0f || available.y <= 0.0f)\n            return std::nullopt;\n        const float scale = std::min(available.x / width, available.y / height);\n        ImGui::PushStyleVar(ImGuiStyleVar_ImageBorderSize, 0.0f);\n        ImGui::Image(texture,\n            ImVec2(width * scale, height * scale),\n            flip_y ? ImVec2(0, 1) : ImVec2(0, 0),\n            flip_y ? ImVec2(1, 0) : ImVec2(1, 1));\n        ImGui::PopStyleVar();\n        const ImVec2 top_left = ImGui::GetItemRectMin();\n        const ImVec2 bottom_right = ImGui::GetItemRectMax();\n        if (!ImGui::IsItemHovered() ||\n            !ImGui::IsMouseClicked(ImGuiMouseButton_Left))\n            return std::nullopt;\n        const ImVec2 mouse = ImGui::GetMousePos();\n        const float u = (mouse.x - top_left.x) / (bottom_right.x - top_left.x);\n        float v = (mouse.y - top_left.y) / (bottom_right.y - top_left.y);\n        if (u < 0.0f || u >= 1.0f || v < 0.0f || v >= 1.0f)\n            return std::nullopt;\n        if (flip_y)\n            v = 1.0f - v;\n        return PickPixel{\n            std::clamp(static_cast<int>(std::floor(u * width)), 0, width - 1),\n            std::clamp(\n                static_cast<int>(std::floor(v * height)), 0, height - 1)};\n    }","id":"engine-viewport-picking-section-2","capture":{"guide_id":"engine-viewport-picking","section_index":1,"scene":"example-engine-viewport-picking-02","mode":"direct","caption":"掲載コードを実行した表示です。","backend":"DirectX 11 / WARP","code_sha256":"df8c22521f749433b7fd3133baae797f8cb9cfa0270dd1c04909e39ba32be25f","image_sha256":"1a597a486a7415f00dfd77c5103d9fdf6f7aa1f030dbf11f34992ad0044a568a","fixture":"auto pixel=DrawSceneImage(Texture(),256,256,false); if(pixel) ImGui::SetTooltip(\"Picked pixel: %d, %d\",pixel->x,pixel->y);","initialization":""}},{"title":"DPIは、表示座標と描画先サイズを分けると整理しやすい","paragraphs":["マウス位置とGetItemRectMin/Max()は同じImGuiの画面座標で比べます。上の比率計算にDPI倍率をもう一度掛ける必要はありません。画像の横幅の半分をクリックしたら、描画先が何ピクセルでもuは0.5になります。","高DPI環境でレンダーターゲットを何ピクセルにするかは別の判断です。次は表示領域と、アプリが把握する対応するフレームバッファー倍率からサイズを決める例です。Multi-viewportではメインウィンドウの倍率をすべてへ流用せず、対象OSウィンドウの倍率を渡してください。"],"code":"#include \"imgui.h\"\n#include <algorithm>\n#include <cmath>\n    struct TargetExtent\n    {\n        int width;\n        int height;\n    };\n    TargetExtent ChooseTargetExtent(\n        ImVec2 content_size, ImVec2 framebuffer_scale)\n    {\n        const float width = std::max(content_size.x, 1.0f) *\n                            std::max(framebuffer_scale.x, 0.1f);\n        const float height = std::max(content_size.y, 1.0f) *\n                             std::max(framebuffer_scale.y, 0.1f);\n        return {std::clamp(static_cast<int>(std::lround(width)), 1, 8192),\n            std::clamp(static_cast<int>(std::lround(height)), 1, 8192)};\n    }","id":"engine-viewport-picking-section-3","capture":{"guide_id":"engine-viewport-picking","section_index":2,"scene":"example-engine-viewport-picking-03","mode":"result","caption":"掲載関数をサンプル引数で呼び、結果を確認する表示を撮影用に添えています。","backend":"DirectX 11 / WARP","code_sha256":"417488fa31376b48a2ded830310b8c7428851d352958206b2238703707f75eb5","image_sha256":"f1ed384aaeb2f0c163c77c7112421f2cd2351766d29610949ff23876dcbdec4f","fixture":"auto value=ChooseTargetExtent(ImVec2(640,360),ImVec2(1.5f,1.5f)); ImGui::TextUnformatted(\"Input: content 640 x 360 / framebuffer scale 1.5\"); ImGui::Separator(); ImGui::Text(\"Render target: %d x %d\",value.width,value.height);","initialization":""}},{"title":"GPUの読み戻し結果は、少し遅れて届くかもしれない","paragraphs":["IDバッファーを使う場合、クリックした瞬間にGPU待ちをすると画面が引っかかることがあります。実際のエンジンでは読み戻しを非同期にし、要求時のシーンID、描画先の世代、マウス座標を一緒に保持する設計を検討します。","結果が届く前にシーンを閉じたり、物体を削除したりすることもあります。**返ってきたIDが今も有効かを検証してから選択を更新**しましょう。Image()がピクセルを読んだり、3D物体を選択してくれるわけではありません。"],"id":"engine-viewport-picking-section-4"},{"title":"四隅を押してから、ギズモへ進もう","paragraphs":["まず左上・右上・左下・右下をクリックして、期待したピクセルへ変換されるか確かめます。次にウィンドウのサイズ変更と表示倍率変更を試し、画像外の余白ではピックしないことを確認しましょう。"],"bullets":["ピッキング対象の画像とIDバッファーは同じカメラ、同じ描画範囲、同じサイズに揃えます。","カメラ操作やImGuizmoの操作中は選択ピックを抑制し、1回のクリックが複数操作へ流れないよう優先順位を決めます。","部分UVでテクスチャを切り出す場合は、0〜1の画像座標をそのUV範囲へ写してからピクセルへ変換します。"],"id":"engine-viewport-picking-section-5"}],"sources":[{"title":"Dear ImGui v1.93.0: 公開APIと各関数の契約","url":"https://github.com/ocornut/imgui/blob/v1.93.0/imgui.h"},{"title":"公式FAQ: ID・入力・アプリとの役割分担","url":"https://github.com/ocornut/imgui/blob/v1.93.0/docs/FAQ.md"}],"image":"guide-engine-workbench","image_scene":"example-engine-viewport-picking-02","image_caption":"","reading":{"goal":"表示した画像の範囲から、ピッキング用の座標を求められる。","when":"Sceneビューのクリック位置がずれるとき","question":"Sceneパネルの左上とImage()の左上は、必ず同じですか？","answer":"余白やタイトルバーなどで異なります。直前のImage()の矩形を基準にし、表示座標と描画先のピクセル数も分けて扱います。"}},{"id":"engine-play-modes","category":"engine","level":"advanced","minutes":22,"title":"Play・Pause・Stepを付ける：編集したシーンを守って試す","summary":"ちょっと動かして、止めて、1フレームだけ進める。ゲームを試しやすくしながら、編集中のシーンをうっかり上書きしない仕組みを作ります。","related_api":["ImGui::Button","ImGui::BeginDisabled","ImGui::EndDisabled","ImGui::SameLine","ImGui::Text"],"related_guides":["engine-editor-architecture","engine-input-focus","engine-safe-deletion","engine-unsaved-scene","engine-fixed-update"],"tags":["Playモード","Pause","Step","シーン複製"],"sections":[{"title":"ボタンより先に、3つの状態を決めよう","paragraphs":["ここではEdit、Playing、Pausedの3状態を用意します。Editでは編集用データを操作し、Playingでは実行用データを更新し、Pausedでは実行用データを表示したまま更新を止めます。StepはPausedのときだけ、決めた時間ぶん更新する操作です。","**UIの更新とゲームの更新は別**です。Pause中もNewFrame()からUI描画までを続けないと、再開ボタンまで動かなくなってしまいます。音声や物理も止めるなら、各システムへ状態を伝える処理はアプリ側で用意します。"],"id":"engine-play-modes-section-1"},{"title":"状態遷移が見える、小さな実験を作る","paragraphs":["次の例は数値xを動かすだけの試作です。Playingは呼び出し元のdelta_seconds、Stepは1/60秒ぶん進めます。本物の固定更新では、Stepを「固定更新1回」に結び付けてください。"],"code":"#include \"imgui.h\"\n    enum class RunMode\n    {\n        Edit,\n        Playing,\n        Paused\n    };\n    struct SimulationState\n    {\n        RunMode mode = RunMode::Edit;\n        float x = 0.0f;\n    };\n    void DrawSimulationControls(SimulationState & state, float delta_seconds)\n    {\n        bool step = false;\n        if (ImGui::Begin(\"Playback\"))\n        {\n            if (state.mode == RunMode::Edit)\n            {\n                if (ImGui::Button(\"Play\"))\n                    state.mode = RunMode::Playing;\n            }\n            else\n            {\n                if (ImGui::Button(\"Stop\"))\n                    state.mode = RunMode::Edit;\n                ImGui::SameLine();\n                if (ImGui::Button(\n                        state.mode == RunMode::Playing ? \"Pause\" : \"Resume\"))\n                    state.mode = state.mode == RunMode::Playing\n                                     ? RunMode::Paused\n                                     : RunMode::Playing;\n                ImGui::SameLine();\n                ImGui::BeginDisabled(state.mode != RunMode::Paused);\n                step = ImGui::Button(\"Step\");\n                ImGui::EndDisabled();\n            }\n            ImGui::Text(\"Position: %.3f\", state.x);\n        }\n        ImGui::End();\n        if (state.mode == RunMode::Playing)\n            state.x += delta_seconds;\n        else if (state.mode == RunMode::Paused && step)\n            state.x += 1.0f / 60.0f;\n    }","id":"engine-play-modes-section-2","capture":{"guide_id":"engine-play-modes","section_index":1,"scene":"example-engine-play-modes-02","mode":"direct","caption":"掲載コードを実行した表示です。","backend":"DirectX 11 / WARP","code_sha256":"37d3d14e139cd15507184a4fe4dc47f59d2eaacd2e12cc63b823bb359b674ea3","image_sha256":"26ee24a5169ba7a67d1afd6da8507e4d63a1d271949e507d3a3f526427f13f06","fixture":"static SimulationState state; DrawSimulationControls(state,ImGui::GetIO().DeltaTime);","initialization":""}},{"title":"Playを押したら、実行用のシーンを複製する","paragraphs":["上の試作は同じxを使っていますが、ゲーム用には編集シーンと実行シーンを分けましょう。次は値だけを持つ小さなSceneをコピーし、停止時に実行シーンを破棄する例です。Saveの対象は常にedit_sceneと決めておくと、実行中の落下位置を保存する事故を防げます。","この例のvectorは値コピーで独立します。実際のシーンにポインター、物理ボディ、GPUリソース、スクリプトがある場合は、単なるコピー代入だけでは不十分です。**共有してよいアセットと、実行ごとに作る状態を区別**してください。"],"code":"#include \"imgui.h\"\n#include <optional>\n#include <vector>\n    struct SceneEntity\n    {\n        int id;\n        float height;\n    };\n    struct SceneData\n    {\n        std::vector<SceneEntity> entities;\n    };\n    struct EditorSession\n    {\n        SceneData edit_scene;\n        std::optional<SceneData> play_scene;\n    };\n    void DrawSceneSession(EditorSession & session)\n    {\n        if (!session.play_scene)\n        {\n            if (ImGui::Button(\"Play copy\"))\n                session.play_scene = session.edit_scene;\n        }\n        else\n        {\n            if (ImGui::Button(\"Stop and discard runtime changes\"))\n                session.play_scene.reset();\n        }\n        ImGui::TextUnformatted(\n            session.play_scene ? \"Runtime copy\" : \"Editing source\");\n    }","id":"engine-play-modes-section-3","capture":{"guide_id":"engine-play-modes","section_index":2,"scene":"example-engine-play-modes-03","mode":"direct","caption":"掲載コードを実行した表示です。","backend":"DirectX 11 / WARP","code_sha256":"ec4f1b4e6ca7ea7727b6f0679130f65cf63534f74bcf10c849b3cc01bc2d8ece","image_sha256":"59aa65748d8e6b8a7ff5d84ef24a16e9e19112c2a8c115ad2e73a0907b517a86","fixture":"static EditorSession session; DrawSceneSession(session);","initialization":""}},{"title":"再開した瞬間に、大きく時間が進むのを防ぐ","paragraphs":["Pauseしていた実時間をそのまま次のdelta timeへ入れると、再開直後に物体が飛ぶことがあります。ゲーム時計を独立させ、Pause中の時間は進めないか、固定更新のアキュムレーターを適切に扱います。","Play開始・停止時には、選択中Entityがどちらのシーンに属するかも見直します。同じ数値IDがあっても別インスタンスなので、シーンIDを含む選択にするか、開始・終了時に選択を明示的に変換または解除しましょう。"],"id":"engine-play-modes-section-4"},{"title":"「停止したら何が戻るか」を先に決めよう","paragraphs":["位置やHPを元へ戻すのか、カメラ位置は維持するのか、実行中に編集したパラメーターを残すのか。どれもエディターの方針です。最初は「停止すると実行中の変更をすべて破棄」で揃え、必要になった値だけ後から適用できるようにすると分かりやすくなります。"],"bullets":["Playing中のInspectorを読み取り専用にするだけでも、編集先の混同を減らせます。","Stepが物理の固定更新なのか描画フレームなのかを表示に明記しましょう。","セーブ、Undo、選択、ゲーム入力を、モード切り替え時のチェックリストに入れておきましょう。"],"id":"engine-play-modes-section-5"}],"sources":[{"title":"Dear ImGui v1.93.0: 公開APIと各関数の契約","url":"https://github.com/ocornut/imgui/blob/v1.93.0/imgui.h"},{"title":"公式FAQ: 状態管理・入力・アプリ側の責任","url":"https://github.com/ocornut/imgui/blob/v1.93.0/docs/FAQ.md"}],"image":"guide-engine-workbench","image_scene":"example-engine-play-modes-02","image_caption":""},{"id":"engine-undo-redo","category":"engine","level":"advanced","minutes":27,"title":"ドラッグ1回をUndo1回にする：編集の始まりと終わりをつかむ","summary":"スライダーを少し動かしただけで履歴が何十件も増える。そんなUndoを避けるために、ひとまとまりの編集として記録してみましょう。","related_api":["ImGui::DragFloat","ImGui::IsItemActivated","ImGui::IsItemDeactivated","ImGui::IsItemDeactivatedAfterEdit","ImGui::BeginDisabled"],"related_guides":["edit-commit","engine-transform-inspector","extensions-imguizmo","engine-safe-deletion"],"tags":["Undo","Redo","トランザクション","編集確定"],"sections":[{"title":"trueが返るたびに履歴へ積まない","paragraphs":["一度のドラッグを戻すために、Undoを何十回も押さなければならない。値が変わるたびに履歴へ積むと、操作の途中まで一件ずつ記録してしまいます。","ここでは、編集前の値を残し、操作が終わった時点で一件の履歴にまとめます。DragFloat()のtrueは、操作中の値の変更通知として使います。","開始はIsItemActivated()、編集後の終了はIsItemDeactivatedAfterEdit()で調べます。どちらも対象の直後に呼びます。UIが消えたり選択が切り替わったりする場合の確定・取り消しは、後の節で別に扱います。"],"id":"engine-undo-redo-section-1"},{"title":"単一のfloatで、履歴の境界を試す","paragraphs":["before_frameはウィジェットを呼ぶ前の値です。操作が始まったフレームに値も変わる可能性があるので、IsItemActivated()の後に現在値を保存するだけでは遅い場合があります。","以下の型と関数をまとめて使います。履歴はアプリ側が保持し、この関数には毎回同じ項目の値を渡します。別Entityへ切り替えるときの扱いは次の段落で決めましょう。"],"code":"#include \"imgui.h\"\n#include <vector>\n    struct FloatCommand\n    {\n        float before;\n        float after;\n    };\n    struct FloatHistory\n    {\n        std::vector<FloatCommand> undo;\n        std::vector<FloatCommand> redo;\n        bool editing = false;\n        float edit_start = 0.0f;\n    };\n    bool DrawTransactionalFloat(float& value, FloatHistory& history)\n    {\n        const float before_frame = value;\n        const bool changed = ImGui::DragFloat(\"Speed\", &value, 0.1f);\n        if (ImGui::IsItemActivated())\n        {\n            history.editing = true;\n            history.edit_start = before_frame;\n        }\n        if (ImGui::IsItemDeactivatedAfterEdit() && history.editing)\n        {\n            if (history.edit_start != value)\n            {\n                history.undo.push_back({history.edit_start, value});\n                history.redo.clear();\n            }\n        }\n        if (ImGui::IsItemDeactivated())\n            history.editing = false;\n        return changed;\n    }","id":"engine-undo-redo-section-2","capture":{"guide_id":"engine-undo-redo","section_index":1,"scene":"example-engine-undo-redo-02","mode":"direct","caption":"掲載コードを実行した表示です。","backend":"DirectX 11 / WARP","code_sha256":"959250a91b0d6bd8cd18e3f0cfecb57f05979c9cbc04c5a67f2c309b1fd285a4","image_sha256":"8ad7f5d994292820eae2760c36385032c1fe3b04b4ecf9c5a20748cb1e7926c8","fixture":"static float value=1.0f; static FloatHistory history; DrawTransactionalFloat(value,history); ImGui::Text(\"Undo entries: %zu / Redo entries: %zu\",history.undo.size(),history.redo.size());","initialization":""}},{"title":"UndoとRedoは、前後の値を入れ替える操作","paragraphs":["次は独立した、履歴を適用するための最小モデルです。Buttonの無効化は操作できない理由を表し、関数側でも履歴の空判定を行います。実際には履歴操作中に新しい編集操作を始めないよう、編集中の確定方針もつなぎます。"],"code":"#include \"imgui.h\"\n#include <vector>\n    struct ScalarCommand\n    {\n        float before;\n        float after;\n    };\n    struct ScalarHistory\n    {\n        std::vector<ScalarCommand> undo;\n        std::vector<ScalarCommand> redo;\n    };\n    void DrawUndoRedo(float& value, ScalarHistory& history)\n    {\n        ImGui::BeginDisabled(history.undo.empty());\n        const bool undo_requested = ImGui::Button(\"Undo\");\n        ImGui::EndDisabled();\n        if (undo_requested && !history.undo.empty())\n        {\n            const ScalarCommand command = history.undo.back();\n            history.undo.pop_back();\n            value = command.before;\n            history.redo.push_back(command);\n        }\n        ImGui::SameLine();\n        ImGui::BeginDisabled(history.redo.empty());\n        const bool redo_requested = ImGui::Button(\"Redo\");\n        ImGui::EndDisabled();\n        if (redo_requested && !history.redo.empty())\n        {\n            const ScalarCommand command = history.redo.back();\n            history.redo.pop_back();\n            value = command.after;\n            history.undo.push_back(command);\n        }\n    }","id":"engine-undo-redo-section-3","capture":{"guide_id":"engine-undo-redo","section_index":2,"scene":"example-engine-undo-redo-03","mode":"direct","caption":"掲載コードを実行した表示です。","backend":"DirectX 11 / WARP","code_sha256":"2f20e6aa1e5e0e2ae44e996e9d7b370a0184bddc4ab923b8f0615e9a0de39e65","image_sha256":"4ff0ed457065216e08b5dec5d94893fc8906e4a86293b8e931f8aa17b66c0de9","fixture":"static float value=2.0f; static ScalarHistory history; if(capture_frame==0)history.undo.push_back({1.0f,2.0f}); DrawUndoRedo(value,history); ImGui::Text(\"Current value: %.1f / Undo: %zu / Redo: %zu\",value,history.undo.size(),history.redo.size());","initialization":""}},{"title":"項目が消えたときにも、編集中の操作を閉じよう","paragraphs":["別Entityを選んだりInspectorを閉じたりしてウィジェット自体が呼ばれなくなると、その項目のIsItemDeactivatedAfterEdit()をこの関数内で拾えません。**選択変更・パネル終了・シーン切り替えの入口でも、進行中の編集を確定か取り消し**できるようにします。","実際のコマンドには対象のEntity ID、プロパティID、前後の値を保存します。UndoのたびにIDから対象を解決し、削除やシーン切り替えで無効になっていた場合の処理も決めてください。生ポインターを履歴へ残すと、後から解放済みメモリーを触る原因になります。"],"id":"engine-undo-redo-section-4"},{"title":"複数軸やギズモは「ひとつの操作」を定義する","paragraphs":["DragFloat3は内部に複数の入力項目を持つため、単一DragFloatの例をそのまま貼るだけで全軸が1件になるとは限りません。最初はX/Y/Zを別のDragFloatとして扱うか、各軸の編集状態をまとめてTransform全体の操作を開始・確定する管理を用意しましょう。","ImGuizmoなら「操作開始から操作終了まで」を同じ履歴サービスへ渡します。ComboやSelectableでは値が変わらない選択でもIsItemDeactivatedAfterEdit()がtrueになることがあるため、最後に前後の値が実際に違うか調べるのも大切です。"],"id":"engine-undo-redo-section-5"}],"sources":[{"title":"Dear ImGui v1.93.0: 公開APIと各関数の契約","url":"https://github.com/ocornut/imgui/blob/v1.93.0/imgui.h"},{"title":"公式FAQ: 状態管理・入力・アプリ側の責任","url":"https://github.com/ocornut/imgui/blob/v1.93.0/docs/FAQ.md"}],"image":"guide-engine-workbench","image_scene":"example-engine-undo-redo-02","image_caption":"","reading":{"goal":"一度のドラッグを、一件のUndoへまとめられる。","when":"Undoが細かすぎる・選択変更で編集中の値を失うとき","question":"編集中にInspectorを閉じても、終了通知だけで必ず編集を確定できますか？","answer":"項目自体が呼ばれなくなると、その場所で終了通知を拾えません。パネル終了や選択変更の入口でも、確定か取り消しかを決めます。"}},{"id":"engine-content-browser","category":"engine","level":"intermediate","minutes":20,"title":"Content Browserを作ろう：ファイル名よりアセットIDでつなぐ","summary":"画像やマテリアルを一覧から選ぶ画面を作ります。検索、開く操作、読み込み中の表示まで、あとから育てやすい形で始めましょう。","related_api":["ImGui::BeginTable","ImGui::Selectable","ImGui::IsMouseDoubleClicked","ImGui::PushID","ImGui::ProgressBar","ImGui::TextUnformatted"],"related_guides":["engine-drag-drop","image-texture","tables-sorting","engine-asset-references","engine-import-draft"],"tags":["Content Browser","アセット","検索","非同期読み込み"],"sections":[{"title":"UIに渡すのは、アセット台帳のスナップショット","paragraphs":["ファイルシステムを毎フレーム走査するところから始めると、大きなフォルダーでUIが固まりやすくなります。アプリ側でアセット台帳を用意し、UIは表示名、種類、IDを読むだけにすると分担が分かりやすくなります。","**表示名やファイルパスと、アセットの識別子を分けましょう。** 名前変更や移動でもIDを維持する設計なら、マテリアルが参照している画像がすぐ迷子になりません。IDの発行・保存・パスとの対応付けはImGuiの機能ではなく、アセット管理側の仕事です。"],"id":"engine-content-browser-section-1"},{"title":"検索できる、2列の一覧から始める","paragraphs":["フィルターと選択IDは呼び出し元が保持します。ダブルクリックされたIDを返すだけにして、実際に画像ビューアーやマテリアル画面を開く処理は呼び出し元へ任せます。"],"code":"#include \"imgui.h\"\n#include <cstdint>\n#include <optional>\n#include <string>\n#include <vector>\n    struct AssetRow\n    {\n        std::uint64_t id;\n        std::string name;\n        std::string kind;\n    };\n    std::optional<std::uint64_t> DrawAssetBrowser(\n        const std::vector<AssetRow>& assets,\n        ImGuiTextFilter& filter,\n        std::uint64_t& selected_id)\n    {\n        std::optional<std::uint64_t> open_request;\n        filter.Draw(\"Search\");\n        if (ImGui::BeginTable(\"Assets\", 2, ImGuiTableFlags_RowBg))\n        {\n            ImGui::TableSetupColumn(\"Name\");\n            ImGui::TableSetupColumn(\"Type\");\n            ImGui::TableHeadersRow();\n            for (const AssetRow& asset : assets)\n            {\n                if (!filter.PassFilter(asset.name.c_str()))\n                    continue;\n                const std::string id = std::to_string(asset.id);\n                ImGui::PushID(id.c_str());\n                ImGui::TableNextRow();\n                ImGui::TableSetColumnIndex(0);\n                const std::string label = asset.name + \"###asset\";\n                if (ImGui::Selectable(label.c_str(),\n                        selected_id == asset.id,\n                        ImGuiSelectableFlags_AllowDoubleClick))\n                {\n                    selected_id = asset.id;\n                    if (ImGui::IsMouseDoubleClicked(ImGuiMouseButton_Left))\n                        open_request = asset.id;\n                }\n                ImGui::TableSetColumnIndex(1);\n                ImGui::TextUnformatted(asset.kind.c_str());\n                ImGui::PopID();\n            }\n            ImGui::EndTable();\n        }\n        return open_request;\n    }","id":"engine-content-browser-section-2","capture":{"guide_id":"engine-content-browser","section_index":1,"scene":"example-engine-content-browser-02","mode":"direct","caption":"掲載コードを実行した表示です。","backend":"DirectX 11 / WARP","code_sha256":"08ca29e5554b32f259fdfc0370b4dee2ed5d211de6ebb3a8c90fda8c7dcee639","image_sha256":"97b4ad368c2248fcf2ce53689c42764b84acd512ef867a15b68ee2ce5a08b1b4","fixture":"static std::vector<AssetRow> assets{{101,\"Player.mesh\",\"Mesh\"},{102,\"Ground.mat\",\"Material\"},{103,\"Checker.png\",\"Texture\"},{104,\"Main.scene\",\"Scene\"}}; static ImGuiTextFilter filter; static std::uint64_t selected=103; DrawAssetBrowser(assets,filter,selected);","initialization":""}},{"title":"読み込み中も、画面は動くようにする","paragraphs":["重い読み込みはアプリのジョブへ依頼し、UIには状態だけ渡します。下の例は状態の表示だけを担当し、スレッドの起動や同期を隠れた前提にしません。ワーカーとUIが同じ文字列やvectorを同時に書き換えないよう、スナップショットやキューで受け渡しましょう。"],"code":"#include \"imgui.h\"\n#include <algorithm>\n#include <string>\n    enum class ImportState\n    {\n        Idle,\n        Loading,\n        Ready,\n        Failed\n    };\n    struct ImportSnapshot\n    {\n        ImportState state = ImportState::Idle;\n        float progress = 0.0f;\n        std::string message;\n    };\n    void DrawImportStatus(const ImportSnapshot& snapshot)\n    {\n        switch (snapshot.state)\n        {\n        case ImportState::Idle:\n            ImGui::TextUnformatted(\"Select an asset to load.\");\n            break;\n        case ImportState::Loading:\n            ImGui::ProgressBar(std::clamp(snapshot.progress, 0.0f, 1.0f));\n            ImGui::TextUnformatted(snapshot.message.c_str());\n            break;\n        case ImportState::Ready:\n            ImGui::TextUnformatted(\"Ready\");\n            break;\n        case ImportState::Failed:\n            ImGui::TextColored(\n                ImVec4(1.0f, 0.35f, 0.25f, 1.0f), \"Import failed\");\n            ImGui::TextWrapped(\"%s\", snapshot.message.c_str());\n            break;\n        }\n    }","id":"engine-content-browser-section-3","capture":{"guide_id":"engine-content-browser","section_index":2,"scene":"example-engine-content-browser-03","mode":"direct","caption":"掲載コードを実行した表示です。","backend":"DirectX 11 / WARP","code_sha256":"b44cb8442f29790f63215474983785535d650ea8c0e6f48d587efc01d31b9f6a","image_sha256":"72def41baf499401a3f39d0c1c3a01b39ef0d6aa92f20b0e2901a6f1dd6806be","fixture":"ImportSnapshot value; value.state=ImportState::Loading; value.progress=0.65f; value.message=\"Importing Player.mesh (sample job status)\"; DrawImportStatus(value);","initialization":""}},{"title":"サムネイルは、ファイルをImageに渡す機能ではない","paragraphs":["サムネイルを付けるときは、画像のデコードとGPUテクスチャ作成をアセット管理側で行い、その有効な参照をImage()へ渡します。ファイルパスをそのまま渡すことはできません。","画面外のアセットまで毎フレーム読み込み直さず、キャッシュと破棄方針を用意しましょう。**描画で参照したGPUリソースは、GPUの使用が終わるまで生かす**必要があります。選択変更の瞬間に解放するだけでは間に合わないことがあります。"],"id":"engine-content-browser-section-4"},{"title":"次は、Inspectorへドラッグして渡してみよう","paragraphs":["選択と開く操作が安定したら、アセットIDをドラッグ＆ドロップで渡せます。受け取り先が画像、マテリアル、シーンのどれを受け付けるかもアプリ側で検証すると、分かりにくい型違いを減らせます。"],"bullets":["ファイル名は外部データなので、Text(name)ではなくTextUnformatted(name)やText(\"%s\", name)を使います。","大量の一覧は、検索結果を一度組み立ててから必要な行を表示する方針へ進めます。","読み込み失敗は空白のサムネイルだけにせず、状態と短い理由を一緒に見せましょう。"],"id":"engine-content-browser-section-5"}],"sources":[{"title":"Dear ImGui v1.93.0: 公開APIと各関数の契約","url":"https://github.com/ocornut/imgui/blob/v1.93.0/imgui.h"},{"title":"公式FAQ: 状態管理・入力・アプリ側の責任","url":"https://github.com/ocornut/imgui/blob/v1.93.0/docs/FAQ.md"},{"title":"自作エンジン作者の開発記録: アセットとInspectorをつなぐ画面例","url":"https://hanion.dev/post/enik-engine/"}],"image":"guide-engine-workbench","image_scene":"example-engine-content-browser-02","image_caption":""},{"id":"engine-drag-drop","category":"engine","level":"advanced","minutes":22,"title":"物体やアセットをドラッグで渡す：PayloadにはIDを入れよう","summary":"Hierarchyから参照先を選んだり、画像をマテリアルへ割り当てたり。ドラッグ操作を、壊れにくいデータの受け渡しにつなぎます。","related_api":["ImGui::BeginDragDropSource","ImGui::SetDragDropPayload","ImGui::EndDragDropSource","ImGui::BeginDragDropTarget","ImGui::AcceptDragDropPayload","ImGui::EndDragDropTarget"],"related_guides":["engine-content-browser","engine-hierarchy-ids","engine-undo-redo"],"tags":["ドラッグ＆ドロップ","Payload","Asset ID","Entity参照"],"sections":[{"title":"コピーされるのは、渡したバイト列","paragraphs":["SetDragDropPayload()は渡したデータをImGui内部へコピーします。だから小さなIDを値で渡す方法は扱いやすい一方、std::stringやvectorのオブジェクトを丸ごとコピーして、受け取り側でそのまま復元する使い方はできません。","**ポインターより、解決し直せるIDを送る**と寿命を扱いやすくなります。Entityならシーンと世代、Assetなら台帳で管理するIDを含めるなど、対象を間違えない情報を設計しましょう。Payloadの型名は最大32文字で、先頭が_の名前はImGui内部用です。"],"id":"engine-drag-drop-section-1"},{"title":"まずは、同じプロジェクト内のアセットIDを渡す","paragraphs":["次は1つの送信元と受信先を作る独立した例です。受け取ったIDを返しますが、この段階ではマテリアルへの適用は行いません。呼び出し元が台帳で実在と型を調べた後、編集要求として反映します。"],"code":"#include \"imgui.h\"\n#include <cstdint>\n#include <cstring>\n#include <optional>\n    std::optional<std::uint64_t> DrawAssetDropExample(std::uint64_t asset_id)\n    {\n        ImGui::Button(\"Drag asset\");\n        if (ImGui::BeginDragDropSource())\n        {\n            ImGui::SetDragDropPayload(\n                \"EDITOR_ASSET_ID\", &asset_id, sizeof(asset_id));\n            ImGui::Text(\n                \"Asset %llu\", static_cast<unsigned long long>(asset_id));\n            ImGui::EndDragDropSource();\n        }\n        ImGui::Button(\"Drop texture here\");\n        std::optional<std::uint64_t> result;\n        if (ImGui::BeginDragDropTarget())\n        {\n            if (const ImGuiPayload* payload =\n                    ImGui::AcceptDragDropPayload(\"EDITOR_ASSET_ID\"))\n            {\n                if (payload->DataSize == sizeof(std::uint64_t))\n                {\n                    std::uint64_t received = 0;\n                    std::memcpy(&received, payload->Data, sizeof(received));\n                    result = received;\n                }\n            }\n            ImGui::EndDragDropTarget();\n        }\n        return result;\n    }","id":"engine-drag-drop-section-2","capture":{"guide_id":"engine-drag-drop","section_index":1,"scene":"example-engine-drag-drop-02","mode":"direct","caption":"掲載コードを実行した表示です。","backend":"DirectX 11 / WARP","code_sha256":"6c399487b61a642e95b29470f59c002285774a66150df0c78e827d87ed1ac8e0","image_sha256":"5f0eea89b4979f86a19f5399732146734e22e2624dda49b9f2b4851002654fe3","fixture":"DrawAssetDropExample(103);","initialization":""}},{"title":"Entity参照には、所属シーンも持たせる","paragraphs":["ID番号が同じでも、別のシーンの物体かもしれません。次は所属シーンと世代番号も付けたPayloadの型です。送信側もこの型をEDITOR_ENTITY_REFという型名でSetDragDropPayload()へ渡します。"],"code":"#include \"imgui.h\"\n#include <cstdint>\n#include <cstring>\n#include <optional>\n#include <type_traits>\n    struct EntityReference\n    {\n        std::uint64_t scene_id;\n        std::uint32_t entity_id;\n        std::uint32_t generation;\n    };\n    static_assert(std::is_trivially_copyable<EntityReference>::value,\n        \"Payload must be bytes\");\n    std::optional<EntityReference> ReadEntityDrop(std::uint64_t active_scene_id)\n    {\n        std::optional<EntityReference> result;\n        if (ImGui::BeginDragDropTarget())\n        {\n            if (const ImGuiPayload* payload =\n                    ImGui::AcceptDragDropPayload(\"EDITOR_ENTITY_REF\"))\n            {\n                if (payload->DataSize == sizeof(EntityReference))\n                {\n                    EntityReference reference{};\n                    std::memcpy(&reference, payload->Data, sizeof(reference));\n                    if (reference.scene_id == active_scene_id)\n                        result = reference;\n                }\n            }\n            ImGui::EndDragDropTarget();\n        }\n        return result;\n    }","id":"engine-drag-drop-section-3","capture":{"guide_id":"engine-drag-drop","section_index":2,"scene":"example-engine-drag-drop-03","mode":"direct","caption":"掲載コードを実行した表示です。","backend":"DirectX 11 / WARP","code_sha256":"e7230bd4f3d53760286fb3511d2b176b9a2f9a9bfea0739ff7bbcdec3b922c5e","image_sha256":"2ba30abf4941706d9540a9ecf4c745234bce8d9287689e4d7c39f69fbe5dddcd","fixture":"ImGui::Button(\"Entity reference target\",ImVec2(320,60)); auto value=ReadEntityDrop(42); ImGui::TextUnformatted(value?\"Accepted entity\":\"Drag a matching scene/entity payload onto the target.\");","initialization":""}},{"title":"プレビューと、実際の確定は分ける","paragraphs":["通常のAcceptDragDropPayload()は、ドロップが確定したタイミングで受け取る使い方です。AcceptBeforeDeliveryを付けると離す前にも内容を見られますが、その段階で本当の値を毎フレーム書き換えないようにしましょう。確定時はpayload->IsDelivery()で判定します。","受信したImGuiPayload*やpayload->Dataを長期保存しないでください。必要なIDの値を自分のデータへコピーし、後からレジストリーで有効性を調べます。**型名が一致していても、サイズ・所属・対象の存在と用途を検証**するのが受け取り側の役目です。"],"id":"engine-drag-drop-section-4"},{"title":"親の付け替えには、もうひとつ検証が必要","paragraphs":["Hierarchyの親子付け替えで使うなら、自分を自分の子にしたり、子孫を新しい親にしたりする操作を拒否します。この循環チェックはドラッグ＆ドロップAPIでは行われません。","受け取りをUI内で即実行せず、SetParentやSetAssetの編集要求へ変換しておくと、Undoやシーンのdirty更新も同じ入口へまとめられます。BeginDragDropSource/Target()がtrueのときだけ、対応するEndを呼ぶ点も忘れずに揃えましょう。"],"id":"engine-drag-drop-section-5"}],"sources":[{"title":"Dear ImGui v1.93.0: 公開APIと各関数の契約","url":"https://github.com/ocornut/imgui/blob/v1.93.0/imgui.h"},{"title":"公式FAQ: 状態管理・入力・アプリ側の責任","url":"https://github.com/ocornut/imgui/blob/v1.93.0/docs/FAQ.md"}],"image":"guide-engine-workbench","image_scene":"example-engine-drag-drop-02","image_caption":""},{"id":"engine-material-light","category":"engine","level":"intermediate","minutes":20,"title":"マテリアルとライトをその場で調整する：見た目と値を結び付ける","summary":"色、粗さ、光の強さを触りながらSceneで確かめる。見た目を作り込むためのInspectorを、小さな編集用モデルから作ります。","related_api":["ImGui::ColorEdit3","ImGui::SliderFloat","ImGui::DragFloat","ImGui::Checkbox","ImGui::SeparatorText","ImGui::SetItemTooltip"],"related_guides":["engine-transform-inspector","engine-undo-redo","engine-viewport-picking"],"tags":["マテリアル","ライト","PBR","色空間"],"sections":[{"title":"スライダーを動かす前に、どの値かを決めよう","paragraphs":["粗さ0〜1、金属度0〜1のように、シェーダーで使う値の意味をUIへそのまま伝えると調整しやすくなります。ImGuiが材質やライトの描画をするのではなく、**UIで変えた値をアプリがレンダラーへ渡す**という流れです。","色は特に注意が必要です。sRGBの画像テクセルと線形の色係数は同じ数値でも意味が違います。ColorEdit3()がエンジンの色空間を判断して自動変換してくれるわけではないので、編集データの規約を明示しましょう。"],"id":"engine-material-light-section-1"},{"title":"材質の基本3項目を、編集できるようにする","paragraphs":["下の例は線形のベースカラー係数を直接編集するモデルです。色スウォッチを最終レンダリングの見本と考えず、Sceneのプレビューで確認します。roughnessの下限0.04はこの試作用の方針で、glTFなどのデータ仕様そのものの下限を示す値ではありません。"],"code":"#include \"imgui.h\"\n    struct MaterialParameters\n    {\n        float base_color_linear[3] = {0.8f, 0.2f, 0.1f};\n        float roughness = 0.5f;\n        float metallic = 0.0f;\n        bool dirty = false;\n    };\n    bool DrawMaterialProperties(MaterialParameters & material)\n    {\n        ImGui::SeparatorText(\"Material\");\n        bool changed = ImGui::ColorEdit3(\"Base color (linear)\",\n            material.base_color_linear,\n            ImGuiColorEditFlags_Float);\n        ImGui::SetItemTooltip(\"Linear color factor. Check the scene preview.\");\n        changed |= ImGui::SliderFloat(\"Roughness\",\n            &material.roughness,\n            0.04f,\n            1.0f,\n            \"%.3f\",\n            ImGuiSliderFlags_AlwaysClamp);\n        changed |= ImGui::SliderFloat(\"Metallic\",\n            &material.metallic,\n            0.0f,\n            1.0f,\n            \"%.3f\",\n            ImGuiSliderFlags_AlwaysClamp);\n        material.dirty |= changed;\n        return changed;\n    }","id":"engine-material-light-section-2","capture":{"guide_id":"engine-material-light","section_index":1,"scene":"example-engine-material-light-02","mode":"direct","caption":"掲載コードを実行した表示です。","backend":"DirectX 11 / WARP","code_sha256":"dcfd459f1d6a29ce4cb7244170ee5457d13c49807a9d33f3188c48534aced987","image_sha256":"587d824ee9ce9fc12bff7bde6ee8e1e582a3f6fb9a408e6d3943d79cd87e8587","fixture":"static MaterialParameters value; DrawMaterialProperties(value);","initialization":""}},{"title":"HDRの光は、色と強さを分けると扱いやすい","paragraphs":["ライトでは色の比率と明るさの大きさを分けると、光の色を保ったまま強さを調整できます。次のIntensityは説明用の相対値です。実際のエンジンでルーメンやカンデラを採用するなら、ラベルと保存値の単位も合わせてください。","ColorEditFlags_HDRは1を超える値を扱うための指定で、HDRレンダーターゲットやトーンマッピングを自動で有効にする機能ではありません。見た目に反映する描画処理はレンダラー側の担当です。"],"code":"#include \"imgui.h\"\n    struct LightParameters\n    {\n        float color[3] = {1.0f, 0.95f, 0.85f};\n        float intensity = 5.0f;\n        bool casts_shadow = true;\n    };\n    bool DrawLightProperties(LightParameters & light)\n    {\n        ImGui::SeparatorText(\"Light\");\n        bool changed = ImGui::ColorEdit3(\"Color multiplier\",\n            light.color,\n            ImGuiColorEditFlags_Float | ImGuiColorEditFlags_HDR);\n        changed |= ImGui::DragFloat(\"Intensity (relative)\",\n            &light.intensity,\n            0.05f,\n            0.0f,\n            10000.0f,\n            \"%.2f\",\n            ImGuiSliderFlags_AlwaysClamp);\n        changed |= ImGui::Checkbox(\"Cast shadows\", &light.casts_shadow);\n        return changed;\n    }","id":"engine-material-light-section-3","capture":{"guide_id":"engine-material-light","section_index":2,"scene":"example-engine-material-light-03","mode":"direct","caption":"掲載コードを実行した表示です。","backend":"DirectX 11 / WARP","code_sha256":"1c8fe333594b45b48524e4ff78eba110a950bb6a6e0809ebf927b49d3b70e1e6","image_sha256":"b12376fbeb976114e9ccef10784bb6ba7542ab2bb2756575cc868ad027bd92f7","fixture":"static LightParameters value; DrawLightProperties(value);","initialization":""}},{"title":"GPUへ反映する入口を、1か所にまとめよう","paragraphs":["UIはCPU側の編集モデルを変更し、レンダラーがその変更を安全なタイミングでGPUへ送るようにします。コンスタントバッファーへの転送、ディスクリプター更新、シェーダー再生成などを各スライダーの中へ直接散らすと、同期や履歴の追加が難しくなります。","**表示用の値、保存する値、GPUへ送る値の関係を決めておく**と混乱が減ります。sRGB変換をUIとシェーダーで二重に掛けたり、露出を材質色へ焼き込んだりしないようにしましょう。"],"id":"engine-material-light-section-4"},{"title":"同じ条件で見比べられるプレビューを作る","paragraphs":["マテリアルの見た目を比較するときは、カメラ、背景、環境光、露出が揃ったプレビューがあると便利です。球と平面を置くだけでも、粗さや金属度の違いを見つけやすくなります。","次はリセット、変更前後の比較、Undoを加えてみましょう。「触ってみたけれど元の方が良かった」をすぐ戻せると、調整する人も安心して試せます。"],"id":"engine-material-light-section-5"}],"sources":[{"title":"Dear ImGui v1.93.0: 公開APIと各関数の契約","url":"https://github.com/ocornut/imgui/blob/v1.93.0/imgui.h"},{"title":"公式FAQ: ID・入力・アプリとの役割分担","url":"https://github.com/ocornut/imgui/blob/v1.93.0/docs/FAQ.md"},{"title":"Khronos glTF: 線形の色係数とsRGBテクスチャの区別","url":"https://github.com/KhronosGroup/glTF/blob/main/specification/2.0/schema/material.pbrMetallicRoughness.schema.json"}],"image":"guide-engine-workbench","image_scene":"example-engine-material-light-02","image_caption":""},{"id":"engine-safe-deletion","category":"engine","level":"advanced","minutes":23,"title":"削除しても落ちないエディターへ：選択と参照の寿命をそろえる","summary":"物体を消した直後にInspectorでクラッシュ。原因を「ImGuiの不調」にせず、選択IDとデータの寿命から防いでいきましょう。","related_api":["ImGui::Selectable","ImGui::Button","ImGui::BeginDisabled","ImGui::TextUnformatted","ImGui::PushID"],"related_guides":["engine-hierarchy-ids","engine-undo-redo","engine-drag-drop","engine-play-modes"],"tags":["削除","寿命","世代付きハンドル","参照切れ"],"sections":[{"title":"UIは、前のフレームのポインターを覚えすぎない","paragraphs":["Inspectorが選択中コンポーネントの生ポインターを持ち続けると、削除やvectorの再確保で無効になることがあります。**選択はハンドルで保持し、使う直前に有効な対象へ解決する**と、失効をチェックする場所が明確になります。","ここでは配列のslotとgenerationを組み合わせます。同じslotへ別の物体を作ってもgenerationが違えば、古い選択から新しい物体を誤って編集せずに済みます。これはエンジン側の設計で、ImGuiが自動で保証する仕組みではありません。"],"id":"engine-safe-deletion-section-1"},{"title":"世代付きハンドルを、その都度解決する","paragraphs":["以下はslotを再利用する最小モデルです。Resolve()が返すポインターは、その場の表示処理だけで使います。あとで配列を増減する可能性がある場所をまたいで保持しないようにします。","Inspector全体もEntityの安定したハンドルでIDを分けます。編集中の対象を消す・選び直すときは、その編集を確定または取り消してから切り替えると、別のEntityへ入力が引き継がれるのを防げます。"],"code":"#include \"imgui.h\"\n#include <cstdint>\n#include <optional>\n#include <vector>\n    struct EntityHandle\n    {\n        std::uint32_t slot;\n        std::uint32_t generation;\n    };\n    struct EntitySlot\n    {\n        std::uint32_t generation = 1;\n        bool alive = false;\n        float speed = 1.0f;\n    };\n    EntitySlot* Resolve(std::vector<EntitySlot> & slots, EntityHandle handle)\n    {\n        if (handle.slot >= slots.size())\n            return nullptr;\n        EntitySlot& slot = slots[handle.slot];\n        return slot.alive && slot.generation == handle.generation ? &slot\n                                                                  : nullptr;\n    }\n    void DrawSelectedEntity(std::vector<EntitySlot> & slots,\n        std::optional<EntityHandle> & selection)\n    {\n        EntitySlot* entity = selection ? Resolve(slots, *selection) : nullptr;\n        if (!entity)\n        {\n            selection.reset();\n            ImGui::TextUnformatted(\"No valid selection\");\n            return;\n        }\n        ImGui::DragFloat(\"Speed\", &entity->speed, 0.1f);\n    }","id":"engine-safe-deletion-section-2","capture":{"guide_id":"engine-safe-deletion","section_index":1,"scene":"example-engine-safe-deletion-02","mode":"direct","caption":"掲載コードを実行した表示です。","backend":"DirectX 11 / WARP","code_sha256":"448633666de53c7aef64563c3a80f0100ad6d4246dbe48a913b6a861f1eaaca0","image_sha256":"374eed4ef4483371fd26eb381dea3f9b66f63912b14c26265a2be36b82c4f2ff","fixture":"static std::vector<EntitySlot> slots{{1,true,2.5f},{2,true,1.0f}}; static std::optional<EntityHandle> selected=EntityHandle{0,1}; DrawSelectedEntity(slots,selected); ImGui::Text(\"Selection valid: %s\",selected?\"yes\":\"no\");","initialization":""}},{"title":"削除は、全パネルが読み終わってから反映する","paragraphs":["Hierarchyを走査しながら同じ配列を消すと、ループと参照が壊れやすくなります。次の独立した例では、UIが削除要求を積み、呼び出し元が全パネルを処理した後にApplyDeleteQueue()を呼びます。世代が一致しない古い要求は無視します。"],"code":"#include \"imgui.h\"\n#include <cstdint>\n#include <optional>\n#include <vector>\n    struct DeleteHandle\n    {\n        std::uint32_t slot;\n        std::uint32_t generation;\n    };\n    struct DeleteSlot\n    {\n        std::uint32_t generation = 1;\n        bool alive = true;\n    };\n    void DrawDeleteButton(std::optional<DeleteHandle> selection,\n        std::vector<DeleteHandle> & queue)\n    {\n        ImGui::BeginDisabled(!selection.has_value());\n        if (ImGui::Button(\"Delete selected\") && selection)\n            queue.push_back(*selection);\n        ImGui::EndDisabled();\n    }\n    void ApplyDeleteQueue(std::vector<DeleteSlot> & slots,\n        std::vector<DeleteHandle> & queue,\n        std::optional<DeleteHandle> & selection)\n    {\n        for (const DeleteHandle handle : queue)\n        {\n            if (handle.slot >= slots.size())\n                continue;\n            DeleteSlot& slot = slots[handle.slot];\n            if (!slot.alive || slot.generation != handle.generation)\n                continue;\n            slot.alive = false;\n            ++slot.generation;\n            if (selection && selection->slot == handle.slot &&\n                selection->generation == handle.generation)\n                selection.reset();\n        }\n        queue.clear();\n    }","id":"engine-safe-deletion-section-3","capture":{"guide_id":"engine-safe-deletion","section_index":2,"scene":"example-engine-safe-deletion-03","mode":"direct","caption":"掲載コードを実行した表示です。","backend":"DirectX 11 / WARP","code_sha256":"b41c6055e317d77061640d8935bc91d77b7e53e04d5e34f6f92a99cd90351b5c","image_sha256":"aa55c7318d185ddf5ca495fc43dfdabb653fcbd3df70e93ad74e76ed8ae6cff6","fixture":"static std::vector<DeleteSlot> slots(3); static std::vector<DeleteHandle> queue; static std::optional<DeleteHandle> selected=DeleteHandle{0,1}; DrawDeleteButton(selected,queue); ApplyDeleteQueue(slots,queue,selected); ImGui::Text(\"Slot 0 alive: %s / selected: %s\",slots[0].alive?\"yes\":\"no\",selected?\"yes\":\"none\");","initialization":""}},{"title":"消すのは物体だけではない","paragraphs":["選択、Undo履歴、ドラッグPayload、親子関係、スクリプトの参照、非同期ピッキング結果も対象を指しているかもしれません。削除時にすべての参照を直接書き換えるか、アクセス時に無効を返すハンドルへ統一するかを決めましょう。","世代カウンターも有限です。上の例は説明を簡単にするため32bitの加算にしています。長期稼働や極端な再利用を想定する仕組みなら、世代の折り返しやID枯渇の方針も必要です。"],"id":"engine-safe-deletion-section-4"},{"title":"UIが安全でも、GPUの寿命は別に考える","paragraphs":["CPU上の物体を消せても、テクスチャやバッファーをGPUがまだ使っている場合があります。**UIの削除完了とGPUリソースの解放可能時点は別**なので、フェンスなど既存レンダラーの仕組みに従って遅延解放します。","テストでは、編集中のEntityの削除、Undoの直後の削除、ドロップ中の削除、Play停止時のシーン破棄を試しましょう。無効になった選択は「選択なし」など分かる表示へ戻せると、クラッシュを避けるだけでなく使う側も状況を理解できます。"],"id":"engine-safe-deletion-section-5"}],"sources":[{"title":"Dear ImGui v1.93.0: 公開APIと各関数の契約","url":"https://github.com/ocornut/imgui/blob/v1.93.0/imgui.h"},{"title":"公式FAQ: ID・入力・アプリとの役割分担","url":"https://github.com/ocornut/imgui/blob/v1.93.0/docs/FAQ.md"},{"title":"Cubos Team: Entity破棄イベントと参照の整理に関する開発記録","url":"https://cubos.riscadoa.com/blog/release-07/"}],"image":"guide-engine-workbench","image_scene":"example-engine-safe-deletion-02","image_caption":""},{"id":"engine-layout-settings","category":"engine","level":"intermediate","minutes":20,"title":"エディターの設定を保存する：レイアウトとプロジェクトデータを分ける","summary":"次に開いたときも同じ作業画面で始めたい。ウィンドウ配置、パネルの表示設定、シーンの保存を整理して、安心して再開できるようにします。","related_api":["ImGui::LoadIniSettingsFromMemory","ImGui::SaveIniSettingsToMemory","ImGui::GetIO","ImGui::Checkbox","ImGui::Begin"],"related_guides":["labels-hash","docking-layout","docking-config","engine-editor-architecture"],"tags":["設定保存","レイアウト","ini","プロジェクト"],"sections":[{"title":"「保存するもの」は、ひとつではない","paragraphs":["ImGuiのiniにはウィンドウ位置やサイズ、テーブル設定などのUI状態が保存されます。Dockingブランチならドッキング状態も対象です。**シーンの物体や材質、独自のチェック状態まで自動保存されるわけではありません。**","プロジェクト内容と個人の作業レイアウトは分けるのがおすすめです。他の人がシーンを開くたび自分のパネル配置まで上書きされると使いづらくなります。保存先と共有範囲を先に決めましょう。"],"table":{"headers":["保存するもの","保存先の例","保存する担当"],"rows":[["物体・材質・アセット参照","プロジェクトのシーンファイル","エンジンのシリアライザー"],["ウィンドウ・テーブル・Docking配置","ユーザーごとのlayout.ini","ImGuiのiniをアプリが管理"],["表示パネル・表示モード","ユーザー設定ファイル","アプリ独自の設定処理"]]},"id":"engine-layout-settings-section-1"},{"title":"iniを自分で管理したいときは、最初に切り替える","paragraphs":["通常はio.IniFilenameの既定値に従って自動保存されます。独自のプロジェクト設定に組み込むなら、コンテキスト作成後・最初のNewFrame()より前にIniFilenameをnullptrへ設定し、保存済みの文字列を読み込みます。","この関数は毎フレーム呼びません。作業中のレイアウトを毎フレーム読み戻すと、ユーザーが動かしたウィンドウまで元へ戻ってしまいます。"],"code":"#include \"imgui.h\"\n#include <string>\n    void ConfigureManualLayout(const std::string& saved_ini)\n    {\n        // CreateContext()の後、最初のNewFrame()より前に呼ぶ\n        ImGuiIO& io = ImGui::GetIO();\n        io.IniFilename = nullptr;\n        if (!saved_ini.empty())\n            ImGui::LoadIniSettingsFromMemory(\n                saved_ini.data(), saved_ini.size());\n    }","id":"engine-layout-settings-section-2","capture":{"guide_id":"engine-layout-settings","section_index":1,"scene":"example-engine-layout-settings-02","mode":"result","caption":"掲載関数をサンプル引数で呼び、結果を確認する表示を撮影用に添えています。","backend":"DirectX 11 / WARP","code_sha256":"9d05646424d558febd804fa84a5522a91a692460c6b64a7429d7659bc4d7a50e","image_sha256":"70e68b62f21bf759a374649c5a96fa29938d6f45835e30bdfd2774627e92990c","fixture":"ConfigureManualLayout(\"\"); ImGui::TextUnformatted(\"ConfigureManualLayout was called with an empty saved layout.\"); ImGui::Text(\"Automatic ini file: %s\",ImGui::GetIO().IniFilename?ImGui::GetIO().IniFilename:\"disabled\"); ImGui::TextUnformatted(\"Application-managed ini storage is active.\");","initialization":""}},{"title":"保存したい合図が来たら、文字列を自分の保存先へ","paragraphs":["手動管理ではWantSaveIniSettingsを調べ、SaveIniSettingsToMemory()で得た文字列を保存します。戻り値のポインターを長期保持せず、必要ならアプリのstringへコピーしてください。","次は小さなデスクトップツール向けの同期書き込み例です。保存に失敗したらfalseを返し、要求フラグを残します。実製品では一時ファイルからの置き換えや非同期保存を検討し、エラー表示や再試行の間隔も用意しましょう。"],"code":"#include \"imgui.h\"\n#include <cstddef>\n#include <fstream>\n    bool SaveLayoutIfRequested(const char* path)\n    {\n        ImGuiIO& io = ImGui::GetIO();\n        if (!io.WantSaveIniSettings)\n            return true;\n        std::size_t length = 0;\n        const char* ini = ImGui::SaveIniSettingsToMemory(&length);\n        std::ofstream file(path, std::ios::binary | std::ios::trunc);\n        if (!file)\n            return false;\n        file.write(ini, static_cast<std::streamsize>(length));\n        file.close();\n        if (!file)\n            return false;\n        io.WantSaveIniSettings = false;\n        return true;\n    }","id":"engine-layout-settings-section-3","capture":{"guide_id":"engine-layout-settings","section_index":2,"scene":"example-engine-layout-settings-03","mode":"result","caption":"掲載関数をサンプル引数で呼び、結果を確認する表示を撮影用に添えています。","backend":"DirectX 11 / WARP","code_sha256":"10003295c8d1fd291daa3554711e2e56932fdf3b60f0cd1c7aa8a40dd5efc8a6","image_sha256":"1c00345ec4b9af4c102164869d0c666938f4262994dca598673f78598bacacd6","fixture":"if(capture_frame==4)ImGui::GetIO().WantSaveIniSettings=true; const bool saved=SaveLayoutIfRequested(\"build/guide-example-layout.ini\"); std::ifstream file(\"build/guide-example-layout.ini\",std::ios::binary|std::ios::ate); ImGui::Text(\"SaveLayoutIfRequested: %s\",saved?\"true\":\"false\"); ImGui::Text(\"Saved bytes: %lld\",file?(long long)file.tellg():0LL); ImGui::Text(\"WantSaveIniSettings after saving: %s\",ImGui::GetIO().WantSaveIniSettings?\"true\":\"false\");","initialization":""}},{"title":"パネル名が変わると、レイアウトも別物になりやすい","paragraphs":["ImGuiの保存状態はウィンドウのIDと結び付いています。タイトルへ選択中ファイル名を入れるなら、例えばInspector: Cube###Inspectorのように固定IDを残すと、表示名が変わっても同じウィンドウとして扱えます。","アプリ独自のshow_inspectorやshow_content_browserは別途保存してください。古い設定を読むときの既定値や設定バージョンも用意すると、パネルを増やした後の更新が楽になります。"],"id":"engine-layout-settings-section-4"},{"title":"レイアウトを壊しても、戻せる入口を用意しよう","paragraphs":["メニューに「標準レイアウトへ戻す」を置くと、パネルを画面外へ動かしたときも復帰しやすくなります。Dockingの初期配置を適用する処理は、毎フレーム実行せず、初回や明示的なリセット時に限定します。","終了時だけ保存する設計では、強制終了時に設定が失われます。WantSaveIniSettingsへの対応、明示的な保存、終了時の未処理要求の確認を組み合わせ、どこまで復元するかを決めておきましょう。"],"id":"engine-layout-settings-section-5"}],"sources":[{"title":"Dear ImGui v1.93.0: 公開APIと各関数の契約","url":"https://github.com/ocornut/imgui/blob/v1.93.0/imgui.h"},{"title":"公式FAQ: ID・入力・アプリとの役割分担","url":"https://github.com/ocornut/imgui/blob/v1.93.0/docs/FAQ.md"}],"image":"guide-engine-workbench","image_scene":"example-engine-layout-settings-02","image_caption":""},{"id":"engine-input-focus","category":"engine","level":"advanced","minutes":23,"title":"ショートカットとゲーム入力を整理する：いま操作している画面を優先しよう","summary":"Inspectorで名前を入力したらゲームも動いた。そんな二重入力を避けつつ、保存やScene操作のショートカットを使いやすくまとめます。","related_api":["ImGui::Shortcut","ImGui::SetNextItemShortcut","ImGui::IsWindowFocused","ImGui::GetIO","ImGui::IsItemHovered","ImGui::IsKeyDown"],"related_guides":["input-routing","engine-play-modes","engine-viewport-picking","engine-undo-redo"],"tags":["入力","ショートカット","フォーカス","ゲーム入力"],"sections":[{"title":"まずは「誰が使う入力か」を決める","paragraphs":["OSやバックエンドからの入力は、アプリの振り分けにかかわらずImGuiにも渡します。そのうえで外側のゲームへ渡すかをio.WantCaptureMouse / WantCaptureKeyboardで判断するのが基本です。入力をImGuiへ渡す段階で止めると、キーを離したことまで届かなくなります。","エディター内のSceneやGameパネルは、さらにアプリ独自の操作領域です。**外側のゲームへの入力振り分けと、ImGui内のパネル間のショートカットは分けて考える**と整理できます。WantTextInputは画面キーボードなどの要求で、入力キャプチャ全般の代わりにはなりません。"],"id":"engine-input-focus-section-1"},{"title":"パネルの操作は、Shortcutのルーティングを使う","paragraphs":["次の関数は有効なパネル内で毎フレーム呼びます。既定のShortcut()はフォーカス階層を考慮して、同じキーを使う項目どうしを調整します。生のIsKeyPressed()だけで全パネルが同じ操作を起動する構成を避けられます。","Ctrl+Sはアプリ全体の保存要求、Fはそのパネルで選択中の物体へ寄る要求です。要求を返すだけにし、保存やカメラ移動の実装は呼び出し元へ置きます。ルートの登録も必要なので、キーを押したフレームだけ関数を呼ぶ書き方にはしません。"],"code":"#include \"imgui.h\"\n    struct EditorShortcutRequests\n    {\n        bool save = false;\n        bool frame_selection = false;\n    };\n    EditorShortcutRequests DrawEditorShortcuts()\n    {\n        EditorShortcutRequests requests;\n        requests.save = ImGui::Shortcut(\n            ImGuiMod_Ctrl | ImGuiKey_S, ImGuiInputFlags_RouteGlobal);\n        requests.frame_selection = ImGui::Shortcut(ImGuiKey_F);\n        ImGui::SetNextItemShortcut(ImGuiMod_Ctrl | ImGuiKey_S);\n        requests.save |= ImGui::Button(\"Save\");\n        return requests;\n    }","id":"engine-input-focus-section-2","capture":{"guide_id":"engine-input-focus","section_index":1,"scene":"example-engine-input-focus-02","mode":"direct","caption":"掲載コードを実行した表示です。","backend":"DirectX 11 / WARP","code_sha256":"d1a7c467c3f5a10cc6b3f17405ed88de8a70ad3c63f4b3a38a1168d98cbe9dec","image_sha256":"529d34b1884ea352519c29f210b461660245741a5204f0cdc2d42f8e455bf405","fixture":"auto value=DrawEditorShortcuts(); ImGui::Text(\"Save request: %s / Frame selection: %s\",value.save?\"yes\":\"no\",value.frame_selection?\"yes\":\"no\");","initialization":""}},{"title":"外側のゲームへ渡すかを、小さな判定にまとめる","paragraphs":["次はImGui外のゲーム領域向けの基本ゲートです。ゲームの実行状態と、アプリが保持するゲーム領域の操作権に加え、ImGuiが使いたい入力を除外します。ImGuiのNewFrame()前に直前のキャプチャ出力を使ってイベントを振り分ける一般的なループもあるため、実際のバックエンド構成に合わせて読むタイミングを決めてください。","ゲーム側の押下状態を自前で保持する場合は、UIへ切り替わった際に押しっぱなしが残らない設計も必要です。キーアップを処理する方法や、フォーカスを失ったら状態をリセットする方法を用意します。"],"code":"#include \"imgui.h\"\n    struct GameInputPermission\n    {\n        bool mouse;\n        bool keyboard;\n    };\n    GameInputPermission GetExternalGameInputPermission(\n        bool playing, bool owns_game_input)\n    {\n        const ImGuiIO& io = ImGui::GetIO();\n        const bool enabled = playing && owns_game_input;\n        return {enabled && !io.WantCaptureMouse,\n            enabled && !io.WantCaptureKeyboard};\n    }","id":"engine-input-focus-section-3","capture":{"guide_id":"engine-input-focus","section_index":2,"scene":"example-engine-input-focus-03","mode":"result","caption":"掲載関数をサンプル引数で呼び、結果を確認する表示を撮影用に添えています。","backend":"DirectX 11 / WARP","code_sha256":"1b0ddd58b6285bee3cf0ca0684334c937b22d09e350e17909e1f9f0e6489704a","image_sha256":"e51f2425d8e5fe01034b052bbb70a3d3d5f39c7d80dfb62edf81f84250f1a52b","fixture":"auto value=GetExternalGameInputPermission(true,true); ImGui::TextUnformatted(\"Input: playing=true / owns_game_input=true\"); ImGui::Separator(); ImGui::Text(\"Game mouse allowed: %s\",value.mouse?\"yes\":\"no\"); ImGui::Text(\"Game keyboard allowed: %s\",value.keyboard?\"yes\":\"no\");","initialization":""}},{"title":"ImGui内のGameビューは、明示的な操作モードにする","paragraphs":["上のゲートは外側のゲーム領域向けです。ImGuiのウィンドウ内にImageでGameビューを置くと、そのウィンドウ自体が入力をキャプチャするため、そのままではゲーム操作が許可されない場合があります。そこでアプリ側で「Gameビューへ入力を渡す」という明示的なモードを持たせます。","例えばクリックでゲーム操作へ入り、Escで解除し、Inspectorを選んだら解除する、と決めます。キーボード・マウスの独占、カーソルロック、解除キーを一緒に設計し、テキスト欄やモーダルが開いているときは操作へ入らないようにします。単にWantCaptureMouseを常に無視する方法では、UIのクリックまでゲームへ流れます。"],"id":"engine-input-focus-section-4"},{"title":"入力を奪いすぎるフラグに気をつける","paragraphs":["RouteGlobalは、フォーカス中の項目やウィンドウが同じショートカットを登録していると、そちらを尊重する方針です。RouteOverActiveなどで無理に優先すると、InputTextが使うCtrl+AやCtrl+Zをエディター全体の操作が奪ってしまう場合があります。","**文字列編集中のDeleteでEntityを削除しない**ことを確認しましょう。保存、Undo、選択解除、カメラ操作、ゲーム入力の順に「テキスト編集中」「モーダル表示中」「Scene上」「Game操作中」の条件を表にして試すと、二重実行を見つけやすくなります。"],"id":"engine-input-focus-section-5"}],"sources":[{"title":"Dear ImGui v1.93.0: 公開APIと各関数の契約","url":"https://github.com/ocornut/imgui/blob/v1.93.0/imgui.h"},{"title":"公式FAQ: ID・入力・アプリとの役割分担","url":"https://github.com/ocornut/imgui/blob/v1.93.0/docs/FAQ.md"}],"image":"guide-engine-workbench","image_scene":"example-engine-input-focus-02","image_caption":""},{"id":"engine-parent-change","title":"親を変えても、見た目の位置を保とう","summary":"Hierarchyで親を付け替えると、物が急に飛んでしまうことがあります。まずX方向の移動だけに絞り、親子の位置と循環チェックを確かめましょう。","category":"engine","level":"intermediate","minutes":8,"tags":["作って覚える","エディター"],"sections":[{"title":"どんな道具を作る？","paragraphs":["World・Platform・Playerの3つを用意します。ReparentでPlayerの親を選び直し、localとworldの数値を見比べます。**Keep world positionがオンなら、親を変えてもワールド位置を保ちます。**","ここでは位置の関係を確かめるため、3Dモデルではなく数値を表示します。"],"preview_scene":"engine-workshop-engine-parent-change-base","preview_caption":false,"id":"engine-parent-change-section-1"},{"title":"仕組みをつかもう","paragraphs":["ローカル位置は「親から見た位置」、ワールド位置は「シーン全体から見た位置」です。平行移動だけなら、ワールド位置は親の位置とローカル位置を足して求められます。","親を変える前のワールド位置を覚え、新しい親のワールド位置を引けば、新しいローカル位置になります。その前に親をたどり、自分自身が途中に現れる付け替えを拒否します。これが循環の防止です。"],"id":"engine-parent-change-section-2"},{"title":"小さなコードで試してみよう","paragraphs":["Dear ImGuiが表示できるC++17以降のプロジェクトで、次のコードを1つの.cppへ置きます。Begin()/End()の内側からDrawWorkshop()を毎フレーム呼んでください。","Platformを選んでReparentを押します。次に親をPlayer自身へ変えてみると、循環になるためボタンが押せなくなります。"],"code":"#include \"imgui.h\"\n#include <array>\n#include <algorithm>\n\n    struct Entity\n    {\n        const char* name;\n        int parent;\n        float localX;\n    };\n    static std::array<Entity, 3> entities{\n        {{\"World\", -1, 0}, {\"Platform\", 0, 10}, {\"Player\", 0, 3}}};\n    static int newParent = 1;\n    static bool keepWorld = true;\n    static const char* result = \"Not changed\";\n\n    float WorldX(int id)\n    {\n        float x = 0;\n        for (int depth = 0; id >= 0 && depth < int(entities.size()); ++depth)\n        {\n            x += entities[id].localX;\n            id = entities[id].parent;\n        }\n        return x;\n    }\n\n    bool CanParent(int child, int parent)\n    {\n        if (child < 0 || child >= int(entities.size()) || parent < -1 ||\n            parent >= int(entities.size()))\n            return false;\n        for (int depth = 0; parent >= 0 && depth < int(entities.size());\n            ++depth)\n        {\n            if (parent == child)\n                return false;\n            parent = entities[parent].parent;\n        }\n        return parent < 0;\n    }\n\n    void DrawWorkshop()\n    {\n        ImGui::TextUnformatted(\"Reparent Player (X translation only)\");\n        ImGui::Combo(\"New parent\", &newParent, \"World\\0Platform\\0Player\\0\");\n        ImGui::Checkbox(\"Keep world position\", &keepWorld);\n        const bool allowed = CanParent(2, newParent);\n        ImGui::BeginDisabled(!allowed);\n        if (ImGui::Button(\"Reparent\"))\n        {\n            const float before = WorldX(2);\n            entities[2].parent = newParent;\n            if (keepWorld)\n                entities[2].localX = before - WorldX(newParent);\n            result = \"Parent changed\";\n        }\n        ImGui::EndDisabled();\n        if (!allowed)\n            ImGui::TextColored(\n                ImVec4(1, .6f, .3f, 1), \"Rejected: cycle / self-parent\");\n        for (int i = 0; i < int(entities.size()); ++i)\n            ImGui::Text(\"%s : local %.1f / world %.1f\",\n                entities[i].name,\n                entities[i].localX,\n                WorldX(i));\n        ImGui::Separator();\n        ImGui::TextUnformatted(result);\n    }","compare_scenes":["engine-workshop-engine-parent-change-base"],"id":"engine-parent-change-section-3","capture":{"guide_id":"engine-parent-change","section_index":2,"scene":"engine-workshop-engine-parent-change-changed","mode":"direct","caption":"親をPlatformへ変更。PlayerのワールドXは3のまま、ローカルXは-7になります。","backend":"DirectX 11 / WARP","code_sha256":"67ecb08de7dfdf3f60462e4821b6f57ace14d0b5676ffe0f5a75c1fa062d68d1","image_sha256":"4436af1a34b82fde8fce1381f78015375f73147c60c310df432a21278b3616a3","fixture":"","initialization":""}},{"title":"うまく動かないときは","paragraphs":[],"bullets":["この例はX方向の平行移動だけです。回転やスケールがある親では、ワールド行列と親の逆行列を使います。","選択した親が削除されたり、IDが変わったりしていないか確かめます。実エンジンでは配列の添字と永続的なIDを分けましょう。","Undoには、変更前後の親IDとローカル変換を一緒に記録すると戻しやすくなります。"],"id":"engine-parent-change-section-4"}],"related_guides":["engine-hierarchy-ids","gizmo-parent-translation","engine-undo-redo"],"related_api":["ImGui::Combo","ImGui::BeginDisabled"],"libraries":[],"sources":[{"title":"v1.93.0：使うAPIの宣言とコメント","url":"https://github.com/ocornut/imgui/blob/c1aaac65e896a45f81f47a4d68f9959e0f86c859/imgui.h"},{"title":"公式デモ：部品の組み合わせ例","url":"https://github.com/ocornut/imgui/blob/c1aaac65e896a45f81f47a4d68f9959e0f86c859/imgui_demo.cpp"}],"capture_suite":"engine-workshop","image":"guide-engine-workbench","image_scene":"engine-workshop-engine-parent-change-changed","image_caption":""},{"id":"engine-multi-inspector","title":"選んだ物だけ、まとめて値を変えよう","summary":"敵を何体か選び、速度を一度にそろえたい。複数選択のInspectorを、混在表示とApplyボタンから作ります。","category":"engine","level":"intermediate","minutes":8,"tags":["作って覚える","エディター"],"sections":[{"title":"どんな道具を作る？","paragraphs":["PlayerとEnemyを選んだ状態では速度が違うため、Mixed valuesと表示します。New speedへ値を入れ、Apply to selectionを押すと選択中の2体だけが変わります。"],"preview_scene":"engine-workshop-engine-multi-inspector-base","preview_caption":false,"id":"engine-multi-inspector-section-1"},{"title":"仕組みをつかもう","paragraphs":["**混在している値を、表示しただけで書き換えない**のが大切です。表示用の値と、これから適用する値を別に持ちます。","この例ではチェック状態で対象を選び、Applyを押したときだけ配列を更新します。複数選択の操作全体ではなく、「決まった選択集合に同じ変更を加える」部分の例です。"],"id":"engine-multi-inspector-section-2"},{"title":"小さなコードで試してみよう","paragraphs":["Dear ImGuiが表示できるC++17以降のプロジェクトで、次のコードを1つの.cppへ置きます。Begin()/End()の内側からDrawWorkshop()を毎フレーム呼んでください。","速度4でApplyすると、Cameraは8のままです。全項目のチェックを外すとApplyを無効にします。"],"code":"#include \"imgui.h\"\n#include <array>\n\n    struct Object\n    {\n        const char* name;\n        float speed;\n        bool selected;\n    };\n    static std::array<Object, 3> objects{\n        {{\"Player\", 2, true}, {\"Enemy\", 5, true}, {\"Camera\", 8, false}}};\n    static float requestedSpeed = 4;\n    static int changed = 0;\n\n    void DrawWorkshop()\n    {\n        ImGui::TextUnformatted(\"Select targets, then apply one value\");\n        int count = 0;\n        float first = 0;\n        bool mixed = false;\n        for (auto& object : objects)\n        {\n            ImGui::PushID(object.name);\n            ImGui::Checkbox(object.name, &object.selected);\n            ImGui::SameLine();\n            ImGui::Text(\"Speed %.1f\", object.speed);\n            if (object.selected)\n            {\n                if (count == 0)\n                    first = object.speed;\n                else\n                    mixed |= object.speed != first;\n                ++count;\n            }\n            ImGui::PopID();\n        }\n        ImGui::Separator();\n        ImGui::Text(\n            \"%d selected / %s\", count, mixed ? \"Mixed values\" : \"Same value\");\n        ImGui::DragFloat(\"New speed\", &requestedSpeed, .1f, 0, 20);\n        ImGui::BeginDisabled(count == 0);\n        if (ImGui::Button(\"Apply to selection\"))\n        {\n            changed = 0;\n            for (auto& object : objects)\n                if (object.selected && object.speed != requestedSpeed)\n                {\n                    object.speed = requestedSpeed;\n                    ++changed;\n                }\n        }\n        ImGui::EndDisabled();\n        ImGui::Text(\"Changed objects: %d\", changed);\n    }","compare_scenes":["engine-workshop-engine-multi-inspector-base"],"id":"engine-multi-inspector-section-3","capture":{"guide_id":"engine-multi-inspector","section_index":2,"scene":"engine-workshop-engine-multi-inspector-applied","mode":"direct","caption":"選んだ2体だけ速度を4にそろえた後。Cameraの速度8は変わりません。","backend":"DirectX 11 / WARP","code_sha256":"b7c4015bf42617d941b944ccd05b4bbbe92e3cbbf13fe5b747c729b117533864","image_sha256":"9ac18b73db7299be1c8da37c7e12fdb74ce7ed18fcc96129b0d7a7f058f0ccf7","fixture":"","initialization":""}},{"title":"うまく動かないときは","paragraphs":[],"bullets":["先頭の対象の値を毎フレーム全員へコピーすると、混在していた設定が勝手に失われます。","移動量を足す編集と、同じ絶対値へそろえる編集は意味が違います。UIにもどちらか分かる名前を付けましょう。","Undoを付けるなら、対象IDと各対象の変更前後の値を、1回のApplyとしてまとめます。"],"id":"engine-multi-inspector-section-4"}],"related_guides":["engine-transform-inspector","gizmo-group-translation","engine-undo-redo"],"related_api":["ImGui::Checkbox","ImGui::DragFloat","ImGui::BeginDisabled"],"libraries":[],"sources":[{"title":"v1.93.0：使うAPIの宣言とコメント","url":"https://github.com/ocornut/imgui/blob/c1aaac65e896a45f81f47a4d68f9959e0f86c859/imgui.h"},{"title":"公式デモ：部品の組み合わせ例","url":"https://github.com/ocornut/imgui/blob/c1aaac65e896a45f81f47a4d68f9959e0f86c859/imgui_demo.cpp"}],"capture_suite":"engine-workshop","image":"guide-engine-workbench","image_scene":"engine-workshop-engine-multi-inspector-applied","image_caption":""},{"id":"engine-component-menu","title":"Inspectorにコンポーネントを足したり外したり","summary":"LightやColliderの追加ボタンを作ります。UIを表示する条件と、コンポーネントの実体があるかどうかをつなぎましょう。","category":"engine","level":"intermediate","minutes":8,"tags":["作って覚える","エディター"],"sections":[{"title":"どんな道具を作る？","paragraphs":["最初はSphere colliderだけがあります。Lightを選んで追加すると、明るさを編集する欄が現れます。既にある種類は追加できません。"],"preview_scene":"engine-workshop-engine-component-menu-base","preview_caption":false,"id":"engine-component-menu-section-1"},{"title":"仕組みをつかもう","paragraphs":["コンポーネントは、オブジェクトに付ける機能とその設定です。この例は「持っているか」と値を小さな構造体で表します。多数のオブジェクトと機能を管理する、本格的なデータの格納方式までは扱いません。","削除ボタンを押した瞬間に参照中のデータを消すと、その後のUI処理で困ることがあります。ここでは削除要求だけ覚え、その部品を描き終えてから反映します。"],"id":"engine-component-menu-section-2"},{"title":"小さなコードで試してみよう","paragraphs":["Dear ImGuiが表示できるC++17以降のプロジェクトで、次のコードを1つの.cppへ置きます。Begin()/End()の内側からDrawWorkshop()を毎フレーム呼んでください。","Add component nowでLightを足し、Remove Lightで外します。追加し直すと値は初期値へ戻ります。"],"code":"#include \"imgui.h\"\n\n    struct Components\n    {\n        bool light = false, collider = true;\n        float intensity = 1, radius = .5f;\n    };\n    static Components components;\n    static int componentType = 0;\n\n    void DrawWorkshop()\n    {\n        ImGui::TextUnformatted(\"Player / Components\");\n        ImGui::Combo(\n            \"Add component\", &componentType, \"Light\\0Sphere collider\\0\");\n        const bool exists =\n            componentType == 0 ? components.light : components.collider;\n        ImGui::BeginDisabled(exists);\n        if (ImGui::Button(\"Add component now\"))\n        {\n            if (componentType == 0)\n            {\n                components.light = true;\n                components.intensity = 1;\n            }\n            else\n            {\n                components.collider = true;\n                components.radius = .5f;\n            }\n        }\n        ImGui::EndDisabled();\n        if (exists)\n            ImGui::TextUnformatted(\"Already attached\");\n        bool removeLight = false, removeCollider = false;\n        if (components.light &&\n            ImGui::CollapsingHeader(\"Light\", ImGuiTreeNodeFlags_DefaultOpen))\n        {\n            ImGui::DragFloat(\"Intensity\", &components.intensity, .1f, 0, 20);\n            removeLight = ImGui::Button(\"Remove Light\");\n        }\n        if (components.collider && ImGui::CollapsingHeader(\"Sphere collider\",\n                                       ImGuiTreeNodeFlags_DefaultOpen))\n        {\n            ImGui::DragFloat(\"Radius\", &components.radius, .05f, .05f, 10);\n            removeCollider = ImGui::Button(\"Remove Collider\");\n        }\n        // 実体を消す操作は、そのコンポーネントのUIを描いた後にまとめる。\n        if (removeLight)\n            components.light = false;\n        if (removeCollider)\n            components.collider = false;\n        ImGui::Text(\n            \"Attached: %d\", int(components.light) + int(components.collider));\n    }","compare_scenes":["engine-workshop-engine-component-menu-base"],"id":"engine-component-menu-section-3","capture":{"guide_id":"engine-component-menu","section_index":2,"scene":"engine-workshop-engine-component-menu-added","mode":"direct","caption":"Lightを追加した後。Sphere colliderとLightを別々に編集できます。","backend":"DirectX 11 / WARP","code_sha256":"5f88cde318a08b41b4e5a908d53a8d880b0342acee00e286338aa1e51a6d051c","image_sha256":"b019fbf4f4d7dae4d7e197648ce0c1c06ae75d274952e9beae0543db4c720f0c","fixture":"","initialization":""}},{"title":"うまく動かないときは","paragraphs":[],"bullets":["折りたたんでいることと、コンポーネントを持っていないことは別です。開閉状態で存在を判断しないようにします。","本物のColliderなら、物理エンジン側の生成・破棄も必要です。この例のboolを変えるだけで物理形状は作られません。","同じ種類を複数付ける設計では、各コンポーネントにも変わらないIDを用意しましょう。"],"id":"engine-component-menu-section-4"}],"related_guides":["engine-editor-architecture","engine-safe-deletion","engine-transform-inspector"],"related_api":["ImGui::CollapsingHeader","ImGui::Combo","ImGui::PushID"],"libraries":[],"sources":[{"title":"v1.93.0：使うAPIの宣言とコメント","url":"https://github.com/ocornut/imgui/blob/c1aaac65e896a45f81f47a4d68f9959e0f86c859/imgui.h"},{"title":"公式デモ：部品の組み合わせ例","url":"https://github.com/ocornut/imgui/blob/c1aaac65e896a45f81f47a4d68f9959e0f86c859/imgui_demo.cpp"}],"capture_suite":"engine-workshop","image":"guide-engine-workbench","image_scene":"engine-workshop-engine-component-menu-added","image_caption":""},{"id":"engine-prefab-overrides","title":"Prefabと違う値を見つけて、元へ戻そう","summary":"複製元の設定と、シーン内で変えた設定を比べます。「この物だけの変更」を見えるようにする、小さなPrefab Inspectorです。","category":"engine","level":"intermediate","minutes":8,"tags":["作って覚える","エディター"],"sections":[{"title":"どんな道具を作る？","paragraphs":["Prefabの速度は2、インスタンスは4で始まります。違う項目をオレンジで示し、Revert speedやRevert allで元へ戻します。"],"preview_scene":"engine-workshop-engine-prefab-overrides-base","preview_caption":false,"id":"engine-prefab-overrides-section-1"},{"title":"仕組みをつかもう","paragraphs":["Prefabは複製元、インスタンスはそこから作った個別の物です。複製元と異なる設定を、ここではoverride（上書き）と呼びます。","Revertはインスタンスを元へ戻す操作です。Apply to prefabは逆に、インスタンスの値を複製元へ反映します。**変更する向きを混同しない**よう、別のボタンにします。"],"id":"engine-prefab-overrides-section-2"},{"title":"小さなコードで試してみよう","paragraphs":["Dear ImGuiが表示できるC++17以降のプロジェクトで、次のコードを1つの.cppへ置きます。Begin()/End()の内側からDrawWorkshop()を毎フレーム呼んでください。","Revert allの後に速度を変え、Apply to prefabを押してみます。この例で変わるのはメモリー上の2つの設定だけです。"],"code":"#include \"imgui.h\"\n\n    struct Settings\n    {\n        float speed = 2;\n        float jump = 5;\n    };\n    static Settings prefab;\n    static Settings instance{4, 5};\n\n    void DrawWorkshop()\n    {\n        ImGui::TextUnformatted(\n            \"Prefab: Player / Instance: Player in Main.scene\");\n        ImGui::DragFloat(\"Instance speed\", &instance.speed, .1f, 0, 20);\n        const bool speedChanged = instance.speed != prefab.speed;\n        ImGui::SameLine();\n        if (speedChanged && ImGui::SmallButton(\"Revert speed\"))\n            instance.speed = prefab.speed;\n        ImGui::DragFloat(\"Instance jump\", &instance.jump, .1f, 0, 20);\n        if (instance.speed != prefab.speed)\n            ImGui::TextColored(ImVec4(1, .7f, .3f, 1),\n                \"Speed override: %.1f -> %.1f\",\n                prefab.speed,\n                instance.speed);\n        if (instance.jump != prefab.jump)\n            ImGui::TextColored(ImVec4(1, .7f, .3f, 1),\n                \"Jump override: %.1f -> %.1f\",\n                prefab.jump,\n                instance.jump);\n        if (ImGui::Button(\"Revert all\"))\n            instance = prefab;\n        ImGui::SameLine();\n        if (ImGui::Button(\"Apply to prefab\"))\n            prefab = instance;\n        ImGui::Separator();\n        ImGui::Text(\"Prefab speed %.1f / jump %.1f\", prefab.speed, prefab.jump);\n        ImGui::TextUnformatted(\n            \"Memory-only example: no asset file is written.\");\n    }","compare_scenes":["engine-workshop-engine-prefab-overrides-base"],"id":"engine-prefab-overrides-section-3","capture":{"guide_id":"engine-prefab-overrides","section_index":2,"scene":"engine-workshop-engine-prefab-overrides-reverted","mode":"direct","caption":"Revert allを押し、インスタンスの値を元のPrefabへそろえた後。","backend":"DirectX 11 / WARP","code_sha256":"ce4a4585e6a099b87c3f03bd2d6c272e34803f33191459c6ab36fefa426c14ca","image_sha256":"a1496ea5d4af95f876a4b28ba1b50810851c59da968412c9b15339de8f3e564e","fixture":"","initialization":""}},{"title":"うまく動かないときは","paragraphs":[],"bullets":["実際のPrefabでは、元の値が同じになっても「明示的に上書きしている」状態を残したい場合があります。この例は値の差だけで判定します。","Prefabの変更を他のインスタンスへ伝える処理や、ファイル保存は含めていません。","複製元の更新時には、上書きしていない項目だけを追従させるルールも必要になります。"],"id":"engine-prefab-overrides-section-4"}],"related_guides":["engine-multi-inspector","engine-undo-redo","engine-import-draft"],"related_api":["ImGui::DragFloat","ImGui::SmallButton","ImGui::TextColored"],"libraries":[],"sources":[{"title":"v1.93.0：使うAPIの宣言とコメント","url":"https://github.com/ocornut/imgui/blob/c1aaac65e896a45f81f47a4d68f9959e0f86c859/imgui.h"},{"title":"公式デモ：部品の組み合わせ例","url":"https://github.com/ocornut/imgui/blob/c1aaac65e896a45f81f47a4d68f9959e0f86c859/imgui_demo.cpp"}],"capture_suite":"engine-workshop","image":"guide-engine-workbench","image_scene":"engine-workshop-engine-prefab-overrides-reverted","image_caption":""},{"id":"engine-unsaved-scene","title":"シーンを閉じる前に、未保存の変更を確認しよう","summary":"別のシーンを開いた瞬間に編集が消えたら困ります。切り替えをいったん待ち、保存・破棄・キャンセルを選ぶ流れを作ります。","category":"engine","level":"intermediate","minutes":8,"tags":["作って覚える","エディター"],"sections":[{"title":"どんな道具を作る？","paragraphs":["速度を変更したMain.sceneからOpen Arenaを押すと、確認ダイアログが出ます。Cancelなら元の編集画面を保ちます。"],"preview_scene":"engine-workshop-engine-unsaved-scene-base","preview_caption":false,"id":"engine-unsaved-scene-section-1"},{"title":"仕組みをつかもう","paragraphs":["保存済みの値と現在の値が違う状態を、dirty（未保存）と呼びます。次のシーンを開く要求と、実際に切り替える処理を分けることで、選択を待てます。","この例のSaveは、メモリー上の保存用の値を更新するだけです。実アプリでは、**ファイル保存が成功した後にだけ切り替える**ようにします。"],"id":"engine-unsaved-scene-section-2"},{"title":"小さなコードで試してみよう","paragraphs":["Dear ImGuiが表示できるC++17以降のプロジェクトで、次のコードを1つの.cppへ置きます。Begin()/End()の内側からDrawWorkshop()を毎フレーム呼んでください。","Open Arenaから3つの選択を試します。Discard and openを選ぶと、編集中の値を使わずArenaの初期値へ切り替わります。この例はMainからArenaへの切り替え1回に絞り、Arenaを開いた後はOpen Arenaを無効にします。"],"code":"#include \"imgui.h\"\n\n    static float speed = 4, savedSpeed = 2;\n    static float savedMain = 2;\n    static int scene = 0;\n    static bool pendingSwitch = false;\n    static const char* status = \"Editing Main.scene\";\n\n    void SwitchScene()\n    {\n        scene = 1;\n        speed = savedSpeed = 1;\n        pendingSwitch = false;\n        status = \"Opened Arena.scene\";\n    }\n\n    void DrawWorkshop()\n    {\n        ImGui::Text(\"Scene: %s\", scene == 0 ? \"Main.scene\" : \"Arena.scene\");\n        ImGui::DragFloat(\"Player speed\", &speed, .1f, 0, 20);\n        const bool dirty = speed != savedSpeed;\n        ImGui::TextUnformatted(dirty ? \"Unsaved changes *\" : \"Saved\");\n        ImGui::BeginDisabled(scene != 0);\n        if (ImGui::Button(\"Open Arena\"))\n        {\n            if (dirty)\n            {\n                pendingSwitch = true;\n                ImGui::OpenPopup(\"Unsaved scene\");\n            }\n            else\n                SwitchScene();\n        }\n        ImGui::EndDisabled();\n        if (ImGui::BeginPopupModal(\n                \"Unsaved scene\", nullptr, ImGuiWindowFlags_AlwaysAutoResize))\n        {\n            ImGui::TextUnformatted(\"Save changes before opening Arena?\");\n            if (ImGui::Button(\"Save and open\"))\n            {\n                // 実アプリでは保存成功を確かめてから切り替える。この例はメモリー内のみ。\n                savedMain = savedSpeed = speed;\n                SwitchScene();\n                ImGui::CloseCurrentPopup();\n            }\n            ImGui::SameLine();\n            if (ImGui::Button(\"Discard and open\"))\n            {\n                SwitchScene();\n                ImGui::CloseCurrentPopup();\n            }\n            ImGui::SameLine();\n            if (ImGui::Button(\"Cancel\"))\n            {\n                pendingSwitch = false;\n                ImGui::CloseCurrentPopup();\n            }\n            ImGui::EndPopup();\n        }\n        ImGui::TextUnformatted(status);\n        ImGui::Text(\"Main.scene memory snapshot: %.1f\", savedMain);\n        ImGui::TextUnformatted(\n            \"Save here updates a memory snapshot, not a file.\");\n    }","compare_scenes":["engine-workshop-engine-unsaved-scene-base"],"id":"engine-unsaved-scene-section-3","capture":{"guide_id":"engine-unsaved-scene","section_index":2,"scene":"engine-workshop-engine-unsaved-scene-prompt","mode":"direct","caption":"Open Arenaを押した後。保存・破棄・キャンセルの3択で切り替えを待っています。","backend":"DirectX 11 / WARP","code_sha256":"b9d4ecc6039b84c8b9aebdb357401fbea37764751783449b646c9f0363b2cbfa","image_sha256":"f2606e08c98712a59c1e999aad982906adc8cfda2eb7851ed3270f7ec2549139","fixture":"","initialization":""}},{"title":"うまく動かないときは","paragraphs":[],"bullets":["ダイアログを出しただけで先にシーンを破棄すると、Cancelしても戻れません。","保存失敗時は現在のシーンと編集内容を保ち、ダイアログ内で理由を表示しましょう。","実際のdirty管理は変更コマンドや保存時の版番号でも行えます。巨大なシーンを毎フレーム丸ごと比較する必要はありません。"],"id":"engine-unsaved-scene-section-4"}],"related_guides":["popup-workflow","engine-play-modes","engine-undo-redo"],"related_api":["ImGui::OpenPopup","ImGui::BeginPopupModal","ImGui::CloseCurrentPopup"],"libraries":[],"sources":[{"title":"v1.93.0：使うAPIの宣言とコメント","url":"https://github.com/ocornut/imgui/blob/c1aaac65e896a45f81f47a4d68f9959e0f86c859/imgui.h"},{"title":"公式デモ：部品の組み合わせ例","url":"https://github.com/ocornut/imgui/blob/c1aaac65e896a45f81f47a4d68f9959e0f86c859/imgui_demo.cpp"}],"capture_suite":"engine-workshop","image":"guide-engine-workbench","image_scene":"engine-workshop-engine-unsaved-scene-prompt","image_caption":""},{"id":"engine-asset-references","title":"このアセット、消して大丈夫？ 参照元を調べよう","summary":"シェーダーを消したらマテリアルが壊れた。そんな変更を避けるため、選んだアセットを使っている相手を一覧にします。","category":"engine","level":"intermediate","minutes":8,"tags":["作って覚える","エディター"],"sections":[{"title":"どんな道具を作る？","paragraphs":["Lit.shaderを選ぶとPlayer.matとGround.matが参照元として出ます。参照がある間は削除確認を無効にします。再ビルドのボタンで、参照元へ要求が付く様子も見られます。"],"preview_scene":"engine-workshop-engine-asset-references-base","preview_caption":false,"id":"engine-asset-references-section-1"},{"title":"仕組みをつかもう","paragraphs":["アセットは画像やモデルなどの素材データです。参照元を探すときは、「選んだIDをdependencyに持つ相手」を検索します。ファイル名より、変わらないIDでつなぐと名前変更に強くなります。","この例は1アセットにつき直接参照1個だけです。シェーダーの更新でマテリアルを再ビルドする要求を立てますが、実際のコンパイルは行いません。"],"id":"engine-asset-references-section-2"},{"title":"小さなコードで試してみよう","paragraphs":["Dear ImGuiが表示できるC++17以降のプロジェクトで、次のコードを1つの.cppへ置きます。Begin()/End()の内側からDrawWorkshop()を毎フレーム呼んでください。","別のアセットを選び、参照元の数を見比べます。Mark dependents for rebuildを押すと、参照元にrebuild queuedが付きます。"],"code":"#include \"imgui.h\"\n#include <array>\n\n    struct Asset\n    {\n        int id;\n        const char* name;\n        int dependency;\n        int revision = 1;\n        bool rebuild = false;\n    };\n    static std::array<Asset, 4> assets{{{1, \"Lit.shader\", 0},\n        {2, \"Player.mat\", 1},\n        {3, \"Ground.mat\", 1},\n        {4, \"Player.mesh\", 0}}};\n    static int selectedAsset = 0;\n\n    void DrawWorkshop()\n    {\n        ImGui::TextUnformatted(\n            \"Asset references (one direct dependency per asset)\");\n        for (int i = 0; i < int(assets.size()); ++i)\n            if (ImGui::Selectable(assets[i].name, selectedAsset == i))\n                selectedAsset = i;\n        Asset& current = assets[selectedAsset];\n        ImGui::Separator();\n        ImGui::Text(\"Referenced by: %s\", current.name);\n        int references = 0;\n        for (const auto& asset : assets)\n            if (asset.dependency == current.id)\n            {\n                ImGui::BulletText(\"%s%s\",\n                    asset.name,\n                    asset.rebuild ? \" [rebuild queued]\" : \"\");\n                ++references;\n            }\n        if (references == 0)\n            ImGui::TextUnformatted(\"No direct references\");\n        ImGui::BeginDisabled(references != 0);\n        if (ImGui::Button(\"Can delete?\"))\n            ImGui::OpenPopup(\"Deletion check\");\n        ImGui::EndDisabled();\n        if (references != 0)\n            ImGui::TextUnformatted(\n                \"Deletion blocked: replace references first.\");\n        if (ImGui::BeginPopup(\"Deletion check\"))\n        {\n            ImGui::TextUnformatted(\n                \"No direct references. This demo does not delete files.\");\n            ImGui::EndPopup();\n        }\n        if (ImGui::Button(\"Mark dependents for rebuild\"))\n        {\n            ++current.revision;\n            for (auto& asset : assets)\n                if (asset.dependency == current.id)\n                    asset.rebuild = true;\n        }\n        ImGui::Text(\"Revision: %d / importer work is not executed here\",\n            current.revision);\n    }","id":"engine-asset-references-section-3","capture":{"guide_id":"engine-asset-references","section_index":2,"scene":"engine-workshop-engine-asset-references-base","mode":"direct","caption":"Lit.shaderを選ぶとPlayer.matとGround.matが参照元として出ます。参照がある間は削除確認を無効にします。再ビルドのボタンで、参照元へ要求が付く様子も見られます。","backend":"DirectX 11 / WARP","code_sha256":"cb99a8c572584627a76c9d48308915317ecdab1333a50c2ff7751d5058b72509","image_sha256":"8ed72a027b2a5d369b38e677ad14f853bb827b8a5aa4be9d10e4089a960fef23","fixture":"","initialization":""}},{"title":"うまく動かないときは","paragraphs":[],"bullets":["参照がないように見えても、未読込のシーンや外部ファイルが使っている場合があります。実アプリはプロジェクト全体の索引も必要です。","何段も連なる依存関係を更新するときは、同じIDを再訪し続けないように、訪問済みの集合を持ちます。","この画面のCan delete?は条件確認だけで、ファイルは消しません。"],"id":"engine-asset-references-section-4"}],"related_guides":["engine-content-browser","engine-scene-validation","engine-import-draft"],"related_api":["ImGui::Selectable","ImGui::BeginDisabled","ImGui::BulletText"],"libraries":[],"sources":[{"title":"v1.93.0：使うAPIの宣言とコメント","url":"https://github.com/ocornut/imgui/blob/c1aaac65e896a45f81f47a4d68f9959e0f86c859/imgui.h"},{"title":"公式デモ：部品の組み合わせ例","url":"https://github.com/ocornut/imgui/blob/c1aaac65e896a45f81f47a4d68f9959e0f86c859/imgui_demo.cpp"}],"capture_suite":"engine-workshop","image":"guide-engine-workbench","image_scene":"engine-workshop-engine-asset-references-base","image_caption":""},{"id":"engine-import-draft","title":"インポート設定を、Applyするまで下書きにしよう","summary":"チェックを変えるたびに重い再インポートを走らせず、設定をまとめて確定します。色テクスチャと法線マップを例にします。","category":"engine","level":"intermediate","minutes":8,"tags":["作って覚える","エディター"],"sections":[{"title":"どんな道具を作る？","paragraphs":["上が編集中の設定、下が適用済みの設定です。Applyで下へ反映し、Cancel editsで編集中の値を戻します。"],"preview_scene":"engine-workshop-engine-import-draft-base","preview_caption":false,"id":"engine-import-draft-section-1"},{"title":"仕組みをつかもう","paragraphs":["編集中の設定をdraft（下書き）として分けます。値を検査し、通ったときだけ適用済みの設定へコピーして、インポート要求を1回出します。","sRGBは画像の値を色として解釈するときの設定です。法線マップは方向のデータなので、この例ではsRGBをオフにするルールにしています。実際の読み込み・GPU転送は別の処理です。"],"id":"engine-import-draft-section-2"},{"title":"小さなコードで試してみよう","paragraphs":["Dear ImGuiが表示できるC++17以降のプロジェクトで、次のコードを1つの.cppへ置きます。Begin()/End()の内側からDrawWorkshop()を毎フレーム呼んでください。","Normal mapを選び、sRGBをオンへ戻すとApplyできなくなります。Scaleも0以下などを入力してみましょう。"],"code":"#include \"imgui.h\"\n\n    struct ImportOptions\n    {\n        bool srgb = true, mipmaps = true;\n        float scale = 1;\n    };\n    static ImportOptions applied;\n    static ImportOptions draft;\n    static int preset = 0, appliedPreset = 0, importRequests = 0;\n\n    void DrawWorkshop()\n    {\n        ImGui::TextUnformatted(\n            \"Texture import settings / Draft and applied values\");\n        if (ImGui::Combo(\"Preset\", &preset, \"Color texture\\0Normal map\\0\"))\n        {\n            draft.srgb = preset == 0;\n            draft.mipmaps = true;\n        }\n        ImGui::Checkbox(\"sRGB\", &draft.srgb);\n        ImGui::Checkbox(\"Generate mipmaps\", &draft.mipmaps);\n        ImGui::InputFloat(\"Scale\", &draft.scale);\n        const bool valid = draft.scale > 0 && draft.scale <= 10 &&\n                           (preset != 1 || !draft.srgb);\n        if (!valid)\n            ImGui::TextColored(ImVec4(1, .6f, .3f, 1),\n                \"Use scale (0,10]; normal maps use linear data.\");\n        ImGui::BeginDisabled(!valid);\n        if (ImGui::Button(\"Apply import options\"))\n        {\n            applied = draft;\n            appliedPreset = preset;\n            ++importRequests;\n        }\n        ImGui::EndDisabled();\n        ImGui::SameLine();\n        if (ImGui::Button(\"Cancel edits\"))\n        {\n            draft = applied;\n            preset = appliedPreset;\n        }\n        ImGui::Separator();\n        ImGui::Text(\"Applied: sRGB=%s / mipmaps=%s / scale=%.2f\",\n            applied.srgb ? \"yes\" : \"no\",\n            applied.mipmaps ? \"yes\" : \"no\",\n            applied.scale);\n        ImGui::Text(\"Import requests: %d (no file decoding or GPU upload)\",\n            importRequests);\n    }","id":"engine-import-draft-section-3","capture":{"guide_id":"engine-import-draft","section_index":2,"scene":"engine-workshop-engine-import-draft-base","mode":"direct","caption":"上が編集中の設定、下が適用済みの設定です。Applyで下へ反映し、Cancel editsで編集中の値を戻します。","backend":"DirectX 11 / WARP","code_sha256":"3f601dddabd19e1519aa84ee88c51fe4e481a0c1f68ae7c40c62463a8e82047d","image_sha256":"097446aafaf104fd3d48e406c5154eb811f11f93b39767048845fbdb2b855c74","fixture":"","initialization":""}},{"title":"うまく動かないときは","paragraphs":[],"bullets":["UIを変更した時点で適用済みの設定まで上書きすると、Cancelできなくなります。","インポートに失敗した場合は、前の有効なアセットを残し、下書きとエラーを表示する設計にしましょう。","ここで増えるのは要求回数です。画像ファイルの読込やmipmap生成を実行した回数ではありません。"],"id":"engine-import-draft-section-4"}],"related_guides":["edit-commit","engine-content-browser","recipes-async-progress"],"related_api":["ImGui::Combo","ImGui::Checkbox","ImGui::BeginDisabled"],"libraries":[],"sources":[{"title":"v1.93.0：使うAPIの宣言とコメント","url":"https://github.com/ocornut/imgui/blob/c1aaac65e896a45f81f47a4d68f9959e0f86c859/imgui.h"},{"title":"公式デモ：部品の組み合わせ例","url":"https://github.com/ocornut/imgui/blob/c1aaac65e896a45f81f47a4d68f9959e0f86c859/imgui_demo.cpp"}],"capture_suite":"engine-workshop","image":"guide-engine-workbench","image_scene":"engine-workshop-engine-import-draft-base","image_caption":""},{"id":"engine-fixed-update","title":"ゲーム更新を固定刻みにして、1コマずつ進めよう","summary":"描画の速さと、物理・ゲーム更新の速さを分けます。停止中に1回だけ更新するボタンから、時間の持ち方を確かめましょう。","category":"engine","level":"intermediate","minutes":8,"tags":["作って覚える","エディター"],"sections":[{"title":"どんな道具を作る？","paragraphs":["Runningで自動更新し、One fixed tickで1/60秒分を進めます。更新回数、シミュレーション位置、表示用の位置を並べています。"],"preview_scene":"engine-workshop-engine-fixed-update-base","preview_caption":false,"id":"engine-fixed-update-section-1"},{"title":"仕組みをつかもう","paragraphs":["描画1回分の経過時間を蓄え、1/60秒たまるごとにTick()を呼びます。PCの描画が速くても、ゲーム更新は同じ刻みで進められます。","描画時に位置がカクカク飛ぶのを抑えるため、直前と最新の更新位置の「間」を表示します。次の更新までの時間が半分たまったなら、2つの位置の中間です。このように間を埋める計算を補間と呼びます。なめらかになる代わりに、表示は最新の更新位置より最大1/60秒分遅れます。"],"id":"engine-fixed-update-section-2"},{"title":"小さなコードで試してみよう","paragraphs":["Dear ImGuiが表示できるC++17以降のプロジェクトで、次のコードを1つの.cppへ置きます。Begin()/End()の内側からDrawWorkshop()を毎フレーム呼んでください。","停止したままOne fixed tickを押してから、Runningを切り替えます。移動は1秒で1単位の小さな数値例です。"],"code":"#include \"imgui.h\"\n#include <algorithm>\n\n    static bool running = false;\n    static double accumulator = 0;\n    static int ticks = 0;\n    static float position = 0, previous = 0;\n\n    void Tick()\n    {\n        previous = position;\n        position += 1.0f / 60.0f;\n        ++ticks;\n    }\n\n    void DrawWorkshop()\n    {\n        ImGui::Checkbox(\"Running\", &running);\n        ImGui::SameLine();\n        ImGui::BeginDisabled(running);\n        if (ImGui::Button(\"One fixed tick\"))\n            Tick();\n        ImGui::EndDisabled();\n        if (running)\n        {\n            accumulator += std::min(double(ImGui::GetIO().DeltaTime), .25);\n            int steps = 0;\n            while (accumulator >= 1.0 / 60.0 && steps < 8)\n            {\n                Tick();\n                accumulator -= 1.0 / 60.0;\n                ++steps;\n            }\n            // 長い停止からの復帰で、更新の追いつき処理が無限に増えないようにする。\n            if (steps == 8)\n                accumulator = 0;\n        }\n        const float alpha = float(accumulator * 60.0);\n        const float display =\n            running ? previous + (position - previous) * alpha : position;\n        ImGui::Text(\"Fixed ticks: %d / time %.3f s\", ticks, ticks / 60.0);\n        ImGui::Text(\"Simulation %.3f / display %.3f / alpha %.2f\",\n            position,\n            display,\n            alpha);\n        const ImVec2 origin = ImGui::GetCursorScreenPos();\n        ImGui::Dummy(ImVec2(600, 100));\n        ImGui::GetWindowDrawList()->AddCircleFilled(\n            ImVec2(origin.x + 20 + display * 50, origin.y + 50),\n            12,\n            IM_COL32(110, 210, 160, 255));\n    }","compare_scenes":["engine-workshop-engine-fixed-update-base"],"id":"engine-fixed-update-section-3","capture":{"guide_id":"engine-fixed-update","section_index":2,"scene":"engine-workshop-engine-fixed-update-stepped","mode":"direct","caption":"停止中にOne fixed tickを1回押した後。更新回数が1になります。","backend":"DirectX 11 / WARP","code_sha256":"553329906cd68a032c4f86636f33f130f5190af0864b86cc89256cdcd22c669b","image_sha256":"322d2f3d466994b03550708e9aa4d3855b44d6957438e746f44bcbf1677959ce","fixture":"","initialization":""}},{"title":"うまく動かないときは","paragraphs":[],"bullets":["長く止まった分を一度に取り戻そうとすると、更新の追いつき処理だけで重くなります。この例は1描画8回までとし、超えた時間を捨てます。ゲームの時間が実時間より遅れる代わりに負荷を抑える方針です。","入力を毎描画受け取るか、各Tickへどう渡すかも決めましょう。ボタン入力を更新回数分だけ繰り返すと、1回の操作が多重に実行されます。","これは固定刻みの仕組みを見せる例で、特定の物理エンジンは使っていません。"],"id":"engine-fixed-update-section-4"}],"related_guides":["engine-play-modes","debug-frame-timing","engine-hit-window"],"related_api":["ImGui::GetIO","ImGui::Checkbox","ImGui::Button"],"libraries":[],"sources":[{"title":"v1.93.0：使うAPIの宣言とコメント","url":"https://github.com/ocornut/imgui/blob/c1aaac65e896a45f81f47a4d68f9959e0f86c859/imgui.h"},{"title":"公式デモ：部品の組み合わせ例","url":"https://github.com/ocornut/imgui/blob/c1aaac65e896a45f81f47a4d68f9959e0f86c859/imgui_demo.cpp"}],"capture_suite":"engine-workshop","image":"guide-engine-workbench","image_scene":"engine-workshop-engine-fixed-update-stepped","image_caption":""},{"id":"engine-collision-layers","title":"衝突する組み合わせを、表で編集しよう","summary":"PlayerとEnemyは当たる、Enemy同士は当たらない。衝突レイヤーのルールを、見渡しやすいチェック表にします。","category":"engine","level":"intermediate","minutes":8,"tags":["作って覚える","エディター"],"sections":[{"title":"どんな道具を作る？","paragraphs":["行と列に同じレイヤー名を並べています。PlayerとEnemyの交差するチェックを変えると、反対側のEnemyとPlayerも同時に変わります。"],"preview_scene":"engine-workshop-engine-collision-layers-base","preview_caption":false,"id":"engine-collision-layers-section-1"},{"title":"仕組みをつかもう","paragraphs":["レイヤーは衝突判定のために物を分けるグループです。この例では左右の順番で結果が変わらない、対称なルールを使います。","チェックを描くのはImGui、ルールを保持するのはアプリです。物理システムが2つの物を調べる前に、この表を参照して判定するか決めます。"],"id":"engine-collision-layers-section-2"},{"title":"小さなコードで試してみよう","paragraphs":["Dear ImGuiが表示できるC++17以降のプロジェクトで、次のコードを1つの.cppへ置きます。Begin()/End()の内側からDrawWorkshop()を毎フレーム呼んでください。","同じレイヤー同士の対角線も変更できます。縦横が対称なまま保たれることを確かめてください。"],"code":"#include \"imgui.h\"\n\n    static const char* layers[] = {\"Player\", \"Enemy\", \"World\"};\n    static bool collide[3][3] = {\n        {false, true, true}, {true, false, true}, {true, true, false}};\n\n    void DrawWorkshop()\n    {\n        ImGui::TextUnformatted(\n            \"Collision rules / edit both directions together\");\n        if (ImGui::BeginTable(\"Rules\",\n                4,\n                ImGuiTableFlags_Borders | ImGuiTableFlags_SizingStretchSame))\n        {\n            ImGui::TableSetupColumn(\"Layer\");\n            for (const char* layer : layers)\n                ImGui::TableSetupColumn(layer);\n            ImGui::TableHeadersRow();\n            for (int row = 0; row < 3; ++row)\n            {\n                ImGui::TableNextRow();\n                ImGui::TableSetColumnIndex(0);\n                ImGui::TextUnformatted(layers[row]);\n                for (int col = 0; col < 3; ++col)\n                {\n                    ImGui::TableSetColumnIndex(col + 1);\n                    ImGui::PushID(row * 3 + col);\n                    if (ImGui::Checkbox(\"##collide\", &collide[row][col]))\n                        collide[col][row] = collide[row][col];\n                    ImGui::PopID();\n                }\n            }\n            ImGui::EndTable();\n        }\n        ImGui::Text(\n            \"Player vs Enemy: %s\", collide[0][1] ? \"Collide\" : \"Ignore\");\n        ImGui::TextUnformatted(\n            \"The physics system must read this table before testing pairs.\");\n    }","id":"engine-collision-layers-section-3","capture":{"guide_id":"engine-collision-layers","section_index":2,"scene":"engine-workshop-engine-collision-layers-base","mode":"direct","caption":"行と列に同じレイヤー名を並べています。PlayerとEnemyの交差するチェックを変えると、反対側のEnemyとPlayerも同時に変わります。","backend":"DirectX 11 / WARP","code_sha256":"9403e8c72941cffa5699575990ef8992d032943b1bd08bf42d1dc44872802ec2","image_sha256":"d01db3080041a0fd629a8cbe0c1e0037db301f4176fc2e8d2ae3f6216b61f053","fixture":"","initialization":""}},{"title":"うまく動かないときは","paragraphs":[],"bullets":["行・列・チェックのラベルが同じでも、PushIDでセルを区別します。IDが重なると違うセルが連動して見える原因になります。","物理エンジンによってはグループとマスクで表現します。表からバックエンドの設定へ変換する処理が必要です。","この例では衝突そのものは計算せず、組み合わせの編集だけを行います。"],"id":"engine-collision-layers-section-4"}],"related_guides":["tables-sorting","labels-hash","debug-world-overlay"],"related_api":["ImGui::BeginTable","ImGui::Checkbox","ImGui::PushID"],"libraries":[],"sources":[{"title":"v1.93.0：使うAPIの宣言とコメント","url":"https://github.com/ocornut/imgui/blob/c1aaac65e896a45f81f47a4d68f9959e0f86c859/imgui.h"},{"title":"公式デモ：部品の組み合わせ例","url":"https://github.com/ocornut/imgui/blob/c1aaac65e896a45f81f47a4d68f9959e0f86c859/imgui_demo.cpp"}],"capture_suite":"engine-workshop","image":"guide-engine-workbench","image_scene":"engine-workshop-engine-collision-layers-base","image_caption":""},{"id":"engine-camera-frame","title":"選んだ物を、カメラの中央に収めよう","summary":"見失ったオブジェクトへ、Frameボタンで戻ります。2Dの正射影カメラから、中心とズームの求め方を覚えましょう。","category":"engine","level":"intermediate","minutes":8,"tags":["作って覚える","エディター"],"sections":[{"title":"どんな道具を作る？","paragraphs":["黄色い枠が選択対象です。Frame selectionを押すと中央へ移り、画面からはみ出さない倍率に変わります。"],"preview_scene":"engine-workshop-engine-camera-frame-base","preview_caption":false,"id":"engine-camera-frame-section-1"},{"title":"仕組みをつかもう","paragraphs":["対象を囲む最小・最大座標から中心と幅・高さを求めます。カメラの中心をそこへ移し、横と縦の両方が収まる倍率のうち、小さい方を選びます。","0.8を掛けて少し余白を残しています。3Dの透視カメラでは、対象の大きさと画角から距離を求めるなど別の計算になります。"],"id":"engine-camera-frame-section-2"},{"title":"小さなコードで試してみよう","paragraphs":["Dear ImGuiが表示できるC++17以降のプロジェクトで、次のコードを1つの.cppへ置きます。Begin()/End()の内側からDrawWorkshop()を毎フレーム呼んでください。","Frame selectionを押してからZoomを動かし、中心を保ったまま大きさだけ変わることを確認します。"],"code":"#include \"imgui.h\"\n#include <algorithm>\n\n    static ImVec2 center(0, 0);\n    static float pixelsPerUnit = 35;\n    static const ImVec2 minimum(2, 1), maximum(6, 3);\n\n    void DrawWorkshop()\n    {\n        ImGui::TextUnformatted(\n            \"Frame a selected rectangle / 2D orthographic example\");\n        const ImVec2 size(600, 260);\n        if (ImGui::Button(\"Frame selection\"))\n        {\n            center = ImVec2(\n                (minimum.x + maximum.x) * .5f, (minimum.y + maximum.y) * .5f);\n            pixelsPerUnit = .8f * std::min(size.x / (maximum.x - minimum.x),\n                                      size.y / (maximum.y - minimum.y));\n        }\n        ImGui::DragFloat(\"Zoom\", &pixelsPerUnit, 1, 5, 150);\n        ImGui::Text(\"Camera center (%.1f, %.1f)\", center.x, center.y);\n        const ImVec2 origin = ImGui::GetCursorScreenPos();\n        ImGui::Dummy(size);\n        auto screen = [&](ImVec2 world)\n        {\n            return ImVec2(\n                origin.x + size.x * .5f + (world.x - center.x) * pixelsPerUnit,\n                origin.y + size.y * .5f - (world.y - center.y) * pixelsPerUnit);\n        };\n        auto* draw = ImGui::GetWindowDrawList();\n        draw->PushClipRect(\n            origin, ImVec2(origin.x + size.x, origin.y + size.y), true);\n        draw->AddRectFilled(origin,\n            ImVec2(origin.x + size.x, origin.y + size.y),\n            IM_COL32(25, 35, 48, 255));\n        draw->AddLine(screen(ImVec2(-20, 0)),\n            screen(ImVec2(20, 0)),\n            IM_COL32(90, 110, 140, 255));\n        draw->AddLine(screen(ImVec2(0, -20)),\n            screen(ImVec2(0, 20)),\n            IM_COL32(90, 110, 140, 255));\n        draw->AddRectFilled(screen(ImVec2(minimum.x, maximum.y)),\n            screen(ImVec2(maximum.x, minimum.y)),\n            IM_COL32(80, 150, 120, 255));\n        draw->AddRect(screen(ImVec2(minimum.x, maximum.y)),\n            screen(ImVec2(maximum.x, minimum.y)),\n            IM_COL32(255, 205, 100, 255),\n            0.0f,\n            3.0f);\n        draw->PopClipRect();\n    }","id":"engine-camera-frame-section-3","capture":{"guide_id":"engine-camera-frame","section_index":2,"scene":"engine-workshop-engine-camera-frame-base","mode":"direct","caption":"Frame selectionを実際に押し、選んだ矩形を中央へ収めた結果です。","backend":"DirectX 11 / WARP","code_sha256":"e5bf9faec44ae5aa92cd7db1e2474ba1fb2abfbf86bb36f27b265f1ae04f351d","image_sha256":"43d534b5a01680e4124723f742776e2d98674b057fa245c53aefec80e8dcc5b1","fixture":"","initialization":""}},{"title":"うまく動かないときは","paragraphs":[],"bullets":["最小と最大が同じ点だけの対象は、幅・高さが0です。実アプリでは最小の大きさを用意してゼロ除算を防ぎます。","親や回転がある物の囲みは、ローカルの箱をそのまま使わず、ワールド座標で計算します。","この例はDrawListで作った2Dプレビューです。実エンジンでは求めたカメラ設定をレンダラーへ渡します。"],"id":"engine-camera-frame-section-4"}],"related_guides":["engine-viewport-picking","visual-pan-zoom","gizmo-selected-object"],"related_api":["ImGui::GetCursorScreenPos","ImGui::GetWindowDrawList","ImGui::Dummy"],"libraries":[],"sources":[{"title":"v1.93.0：使うAPIの宣言とコメント","url":"https://github.com/ocornut/imgui/blob/c1aaac65e896a45f81f47a4d68f9959e0f86c859/imgui.h"},{"title":"公式デモ：部品の組み合わせ例","url":"https://github.com/ocornut/imgui/blob/c1aaac65e896a45f81f47a4d68f9959e0f86c859/imgui_demo.cpp"}],"capture_suite":"engine-workshop","image":"guide-engine-workbench","image_scene":"engine-workshop-engine-camera-frame-base","image_caption":""},{"id":"engine-tile-painter","title":"マップをマス目で塗る、小さなタイルエディター","summary":"クリックした場所を、配列の何番目へ書けばいい？ 12×8のマップを塗りながら、画面座標とタイル座標をつなぎます。","category":"engine","level":"intermediate","minutes":8,"tags":["作って覚える","エディター"],"sections":[{"title":"どんな道具を作る？","paragraphs":["緑が地面、青が水です。ブラシを選んでキャンバス上をドラッグすると、通ったマスのデータと表示が変わります。"],"preview_scene":"engine-workshop-engine-tile-painter-base","preview_caption":false,"id":"engine-tile-painter-section-1"},{"title":"仕組みをつかもう","paragraphs":["マウス位置からキャンバス左上を引き、1マス30pxで割って列と行を求めます。配列の位置はy×横幅+xです。","**配列へ書く前に、行と列が範囲内か確認します。** 描画はその配列を読み直すので、別の表示用コピーは要りません。"],"id":"engine-tile-painter-section-2"},{"title":"小さなコードで試してみよう","paragraphs":["Dear ImGuiが表示できるC++17以降のプロジェクトで、次のコードを1つの.cppへ置きます。Begin()/End()の内側からDrawWorkshop()を毎フレーム呼んでください。","Waterで数マス塗り、Eraseで消します。Water tilesの数も、実際の配列から数えています。"],"code":"#include \"imgui.h\"\n#include <array>\n#include <algorithm>\n\n    static std::array<int, 96> tiles = []\n    {\n        std::array<int, 96> a{};\n        for (int x = 0; x < 12; ++x)\n            a[7 * 12 + x] = 1;\n        a[6 * 12 + 4] = a[6 * 12 + 5] = 2;\n        return a;\n    }();\n    static int brush = 2;\n\n    void DrawWorkshop()\n    {\n        ImGui::TextUnformatted(\"12 x 8 tile map / drag to paint\");\n        ImGui::RadioButton(\"Erase\", &brush, 0);\n        ImGui::SameLine();\n        ImGui::RadioButton(\"Ground\", &brush, 1);\n        ImGui::SameLine();\n        ImGui::RadioButton(\"Water\", &brush, 2);\n        const float cell = 30;\n        const ImVec2 origin = ImGui::GetCursorScreenPos(),\n                     size(12 * cell, 8 * cell);\n        ImGui::InvisibleButton(\"Tile canvas\", size);\n        if (ImGui::IsItemHovered() && ImGui::IsMouseDown(ImGuiMouseButton_Left))\n        {\n            const ImVec2 mouse = ImGui::GetMousePos();\n            const int x = int((mouse.x - origin.x) / cell),\n                      y = int((mouse.y - origin.y) / cell);\n            if (x >= 0 && x < 12 && y >= 0 && y < 8)\n                tiles[y * 12 + x] = brush;\n        }\n        const ImU32 colors[] = {IM_COL32(38, 47, 60, 255),\n            IM_COL32(110, 170, 100, 255),\n            IM_COL32(80, 145, 220, 255)};\n        auto* draw = ImGui::GetWindowDrawList();\n        for (int y = 0; y < 8; ++y)\n            for (int x = 0; x < 12; ++x)\n            {\n                const ImVec2 a(origin.x + x * cell, origin.y + y * cell),\n                    b(a.x + cell - 1, a.y + cell - 1);\n                draw->AddRectFilled(a, b, colors[tiles[y * 12 + x]]);\n            }\n        ImGui::Text(\n            \"Water tiles: %d\", int(std::count(tiles.begin(), tiles.end(), 2)));\n    }","id":"engine-tile-painter-section-3","capture":{"guide_id":"engine-tile-painter","section_index":2,"scene":"engine-workshop-engine-tile-painter-base","mode":"direct","caption":"緑が地面、青が水です。ブラシを選んでキャンバス上をドラッグすると、通ったマスのデータと表示が変わります。","backend":"DirectX 11 / WARP","code_sha256":"7c3bca12d947f6efa1af184a1b5feab2da877634b427eb7ad6b016cb94ef4953","image_sha256":"375036a213b223473f2a849c0314c8aaaad0a029245b3b9ad3942d8884ca879c","fixture":"","initialization":""}},{"title":"うまく動かないときは","paragraphs":[],"bullets":["拡大やスクロールを追加したら、その移動量と倍率を逆に適用してからタイル座標へ変換します。","速いドラッグでは途中のマスを飛ばすことがあります。線で補間して塗る機能は次の段階として追加しましょう。","Undoを付けるなら、ドラッグの開始から終了までに変えたマスを1回の操作にまとめます。"],"id":"engine-tile-painter-section-4"}],"related_guides":["visual-pan-zoom","visual-marquee","engine-undo-redo"],"related_api":["ImGui::InvisibleButton","ImGui::IsMouseDown","ImGui::GetMousePos"],"libraries":[],"sources":[{"title":"v1.93.0：使うAPIの宣言とコメント","url":"https://github.com/ocornut/imgui/blob/c1aaac65e896a45f81f47a4d68f9959e0f86c859/imgui.h"},{"title":"公式デモ：部品の組み合わせ例","url":"https://github.com/ocornut/imgui/blob/c1aaac65e896a45f81f47a4d68f9959e0f86c859/imgui_demo.cpp"}],"capture_suite":"engine-workshop","image":"guide-engine-workbench","image_scene":"engine-workshop-engine-tile-painter-base","image_caption":""},{"id":"engine-waypoint-preview","title":"巡回する点を動かして、AIの経路を調整しよう","summary":"敵が歩く予定の点を並べ、どの順番で進むかをその場で見ます。障害物のない小さな経路から始めましょう。","category":"engine","level":"intermediate","minutes":8,"tags":["作って覚える","エディター"],"sections":[{"title":"どんな道具を作る？","paragraphs":["黄色い点が巡回先、緑の丸が動く対象です。Pointの座標やSpeedを変えると、次の目的地へ進む動きが変わります。"],"preview_scene":"engine-workshop-engine-waypoint-preview-base","preview_caption":false,"id":"engine-waypoint-preview-section-1"},{"title":"仕組みをつかもう","paragraphs":["目的地との差から方向と距離を求め、速度×経過秒だけ進めます。残り距離がその移動量以下になったら目的地へぴったり合わせ、次の点へ切り替えます。","この例の座標と速度はプレビュー内のピクセルが単位です。ワールドのメートルへ直す場合は、表示用の変換と移動の計算を分けます。"],"id":"engine-waypoint-preview-section-2"},{"title":"小さなコードで試してみよう","paragraphs":["Dear ImGuiが表示できるC++17以降のプロジェクトで、次のコードを1つの.cppへ置きます。Begin()/End()の内側からDrawWorkshop()を毎フレーム呼んでください。","Patrolを止めて点を編集し、Restart patrolで最初の点へ戻してから再開してみましょう。"],"code":"#include \"imgui.h\"\n#include <array>\n#include <cmath>\n#include <algorithm>\n\n    static std::array<ImVec2, 3> points{{{50, 70}, {350, 55}, {260, 210}}};\n    static ImVec2 agent(50, 70);\n    static int targetPoint = 1;\n    static bool patrol = true;\n    static float speed = 80;\n\n    void DrawWorkshop()\n    {\n        ImGui::Checkbox(\"Patrol\", &patrol);\n        ImGui::SameLine();\n        ImGui::SliderFloat(\"Speed (px/s)\", &speed, 10, 200);\n        for (int i = 0; i < 3; ++i)\n        {\n            ImGui::PushID(i);\n            ImGui::DragFloat2(\"Point\", &points[i].x, 1, 0, 450);\n            ImGui::PopID();\n        }\n        if (ImGui::Button(\"Restart patrol\"))\n        {\n            agent = points[0];\n            targetPoint = 1;\n        }\n        if (patrol)\n        {\n            const float dx = points[targetPoint].x - agent.x,\n                        dy = points[targetPoint].y - agent.y;\n            const float distance = std::sqrt(dx * dx + dy * dy),\n                        step = speed * std::min(ImGui::GetIO().DeltaTime, .05f);\n            if (distance <= step)\n            {\n                agent = points[targetPoint];\n                targetPoint = (targetPoint + 1) % 3;\n            }\n            else\n            {\n                agent.x += dx / distance * step;\n                agent.y += dy / distance * step;\n            }\n        }\n        const ImVec2 origin = ImGui::GetCursorScreenPos();\n        ImGui::Dummy(ImVec2(500, 270));\n        auto* draw = ImGui::GetWindowDrawList();\n        draw->PushClipRect(\n            origin, ImVec2(origin.x + 500, origin.y + 270), true);\n        auto screen = [&](ImVec2 p)\n        { return ImVec2(origin.x + p.x, origin.y + p.y); };\n        for (int i = 0; i < 3; ++i)\n        {\n            draw->AddLine(screen(points[i]),\n                screen(points[(i + 1) % 3]),\n                IM_COL32(100, 150, 190, 255),\n                2);\n            draw->AddCircleFilled(\n                screen(points[i]), 5, IM_COL32(250, 200, 90, 255));\n        }\n        draw->AddCircleFilled(screen(agent), 10, IM_COL32(110, 230, 160, 255));\n        draw->PopClipRect();\n        ImGui::Text(\n            \"Moving toward point %d / no obstacle avoidance\", targetPoint);\n    }","id":"engine-waypoint-preview-section-3","capture":{"guide_id":"engine-waypoint-preview","section_index":2,"scene":"engine-workshop-engine-waypoint-preview-base","mode":"direct","caption":"黄色い点が巡回先、緑の丸が動く対象です。Pointの座標やSpeedを変えると、次の目的地へ進む動きが変わります。","backend":"DirectX 11 / WARP","code_sha256":"c5ec8d3091afbbf8121176d74d169f1ba36f92af60c8052d8ec8ac1ecf483e3f","image_sha256":"a4c6743dd5816e4ead540676cc83bee08a59b980f7f222f40b7e6d3df9362044","fixture":"","initialization":""}},{"title":"うまく動かないときは","paragraphs":[],"bullets":["到着時に進みすぎると、目的地を行き来して振動します。残り距離との比較があるか確認します。","障害物回避やNavMeshは含めていません。点へ向かって直線で動く確認用の例です。","表示範囲から出た点はクリップされます。編集した数値がプレビューの範囲に収まるかも確認しましょう。"],"id":"engine-waypoint-preview-section-4"}],"related_guides":["node-state-machine","debug-world-overlay","engine-fixed-update"],"related_api":["ImGui::DragFloat2","ImGui::GetIO","ImGui::GetWindowDrawList"],"libraries":[],"sources":[{"title":"v1.93.0：使うAPIの宣言とコメント","url":"https://github.com/ocornut/imgui/blob/c1aaac65e896a45f81f47a4d68f9959e0f86c859/imgui.h"},{"title":"公式デモ：部品の組み合わせ例","url":"https://github.com/ocornut/imgui/blob/c1aaac65e896a45f81f47a4d68f9959e0f86c859/imgui_demo.cpp"}],"capture_suite":"engine-workshop","image":"guide-engine-workbench","image_scene":"engine-workshop-engine-waypoint-preview-base","image_caption":""},{"id":"engine-particle-preview","title":"パーティクルの設定を、小さなプレビューで試そう","summary":"寿命や重力を変えたら、粒の飛び方はどう変わります？ 同じ初期条件から繰り返し再生できる道具を作ります。","category":"engine","level":"intermediate","minutes":8,"tags":["作って覚える","エディター"],"sections":[{"title":"どんな道具を作る？","paragraphs":["32個の粒を一度に飛ばします。Gravityで落下、Lifetimeで消えるまでの時間を調整し、Restart burstで同じ初期状態へ戻します。"],"preview_scene":"engine-workshop-engine-particle-preview-base","preview_caption":false,"id":"engine-particle-preview-section-1"},{"title":"仕組みをつかもう","paragraphs":["粒ごとに位置・速度・経過時間を持ちます。速度と位置を更新し、寿命に近づくほど透明にします。初期速度を同じ式で作ると、設定を変えた結果を比べやすくなります。","この例はCPUで更新し、ImDrawListへ丸を描くプレビューです。ゲーム側のGPUパーティクルを動かしているわけではありません。"],"id":"engine-particle-preview-section-2"},{"title":"小さなコードで試してみよう","paragraphs":["Dear ImGuiが表示できるC++17以降のプロジェクトで、次のコードを1つの.cppへ置きます。Begin()/End()の内側からDrawWorkshop()を毎フレーム呼んでください。","Animateを止めて設定を変え、Restart burstでやり直します。寿命を短くすると、Aliveの数が0へ減ることも確認できます。"],"code":"#include \"imgui.h\"\n#include <array>\n#include <cmath>\n#include <algorithm>\n\n    struct Particle\n    {\n        float x, y, vx, vy, age;\n    };\n    static std::array<Particle, 32> particles;\n    static bool started = false, animate = true;\n    static float gravity = 80, lifetime = 2;\n\n    void Restart()\n    {\n        for (int i = 0; i < int(particles.size()); ++i)\n        {\n            const float angle = i * 2.39996f;\n            particles[i] = {\n                250, 170, std::cos(angle) * 85, -80 + std::sin(angle) * 70, 0};\n        }\n        started = true;\n    }\n\n    void DrawWorkshop()\n    {\n        if (!started)\n            Restart();\n        ImGui::Checkbox(\"Animate\", &animate);\n        ImGui::SameLine();\n        if (ImGui::Button(\"Restart burst\"))\n            Restart();\n        ImGui::SliderFloat(\"Gravity\", &gravity, 0, 200);\n        ImGui::SliderFloat(\"Lifetime (s)\", &lifetime, .2f, 4);\n        if (animate)\n            for (auto& p : particles)\n                if (p.age < lifetime)\n                {\n                    const float dt = std::min(ImGui::GetIO().DeltaTime, .05f);\n                    p.vy += gravity * dt;\n                    p.x += p.vx * dt;\n                    p.y += p.vy * dt;\n                    p.age += dt;\n                }\n        const ImVec2 origin = ImGui::GetCursorScreenPos();\n        ImGui::Dummy(ImVec2(500, 300));\n        auto* draw = ImGui::GetWindowDrawList();\n        int alive = 0;\n        draw->PushClipRect(\n            origin, ImVec2(origin.x + 500, origin.y + 300), true);\n        for (const auto& p : particles)\n            if (p.age < lifetime)\n            {\n                ++alive;\n                const int alpha = int(255 * (1 - p.age / lifetime));\n                draw->AddCircleFilled(ImVec2(origin.x + p.x, origin.y + p.y),\n                    4,\n                    IM_COL32(255, 180, 80, alpha));\n            }\n        draw->PopClipRect();\n        ImGui::Text(\"Alive: %d / 32 (CPU preview)\", alive);\n    }","id":"engine-particle-preview-section-3","capture":{"guide_id":"engine-particle-preview","section_index":2,"scene":"engine-workshop-engine-particle-preview-base","mode":"direct","caption":"32個の粒を一度に飛ばします。Gravityで落下、Lifetimeで消えるまでの時間を調整し、Restart burstで同じ初期状態へ戻します。","backend":"DirectX 11 / WARP","code_sha256":"aebcd2498cd3bbf0ea97a6bfa5eb3292136e5bde506dcdbbc311c1e3ffb24da9","image_sha256":"560f5f8530dc46b3011c1ee711b3430b97ad13685b75319733aa3ee3a6ca5f61","fixture":"","initialization":""}},{"title":"うまく動かないときは","paragraphs":[],"bullets":["消えた粒を配列から消す代わりに、この例は寿命を超えたものを更新・描画しません。","フレームごとに初期化し直すと、いつまでも粒が発射直後の場所に残ります。","この積分方法は小さなプレビュー向けです。厳密な再現性が必要なら固定刻み更新や乱数の種の管理も検討しましょう。"],"id":"engine-particle-preview-section-4"}],"related_guides":["engine-fixed-update","visual-animation","debug-render-statistics"],"related_api":["ImGui::SliderFloat","ImGui::GetIO","ImGui::GetWindowDrawList"],"libraries":[],"sources":[{"title":"v1.93.0：使うAPIの宣言とコメント","url":"https://github.com/ocornut/imgui/blob/c1aaac65e896a45f81f47a4d68f9959e0f86c859/imgui.h"},{"title":"公式デモ：部品の組み合わせ例","url":"https://github.com/ocornut/imgui/blob/c1aaac65e896a45f81f47a4d68f9959e0f86c859/imgui_demo.cpp"}],"capture_suite":"engine-workshop","image":"guide-engine-workbench","image_scene":"engine-workshop-engine-particle-preview-base","image_caption":""},{"id":"engine-hit-window","title":"攻撃が当たるフレームを、見える形で調整しよう","summary":"見た目のアニメーションと、当たり判定の有効時間を合わせます。現在フレームを動かして、いつ判定が出るか確かめましょう。","category":"engine","level":"intermediate","minutes":8,"tags":["作って覚える","エディター"],"sections":[{"title":"どんな道具を作る？","paragraphs":["下の帯が0〜29フレームで、オレンジの部分が有効区間です。現在フレームが区間内にあると、キャラクターの横に赤い枠が出ます。"],"preview_scene":"engine-workshop-engine-hit-window-base","preview_caption":false,"id":"engine-hit-window-section-1"},{"title":"仕組みをつかもう","paragraphs":["この例は開始・終了の両方を含む区間です。開始≤現在≤終了なら有効にします。開始が終了より後なら、不正な区間として無効にします。","赤い枠は判定の可視化だけです。実際に物へ当たったかの検査と、同じ相手へ何回ダメージを与えるかはゲーム側で処理します。"],"id":"engine-hit-window-section-2"},{"title":"小さなコードで試してみよう","paragraphs":["Dear ImGuiが表示できるC++17以降のプロジェクトで、次のコードを1つの.cppへ置きます。Begin()/End()の内側からDrawWorkshop()を毎フレーム呼んでください。","8〜12の間とその直前・直後を行き来してみます。区間の端を含むかどうかを、まずこの画面で統一しましょう。"],"code":"#include \"imgui.h\"\n#include <algorithm>\n\n    static int currentFrame = 9, activeStart = 8, activeEnd = 12;\n\n    void DrawWorkshop()\n    {\n        ImGui::TextUnformatted(\"Attack preview / inclusive active frame range\");\n        ImGui::SliderInt(\"Current frame\", &currentFrame, 0, 29);\n        ImGui::SliderInt(\"Active start\", &activeStart, 0, 29);\n        ImGui::SliderInt(\"Active end\", &activeEnd, 0, 29);\n        const bool valid = activeStart <= activeEnd;\n        const bool active =\n            valid && currentFrame >= activeStart && currentFrame <= activeEnd;\n        if (!valid)\n            ImGui::TextColored(ImVec4(1, .5f, .3f, 1), \"Start must be <= end\");\n        ImGui::TextUnformatted(active ? \"Hitbox ACTIVE\" : \"Hitbox inactive\");\n        const ImVec2 origin = ImGui::GetCursorScreenPos();\n        ImGui::Dummy(ImVec2(560, 200));\n        auto* draw = ImGui::GetWindowDrawList();\n        draw->AddRectFilled(ImVec2(origin.x + 100, origin.y + 40),\n            ImVec2(origin.x + 155, origin.y + 140),\n            IM_COL32(90, 160, 210, 255));\n        if (active)\n            draw->AddRect(ImVec2(origin.x + 155, origin.y + 65),\n                ImVec2(origin.x + 270, origin.y + 125),\n                IM_COL32(255, 120, 90, 255),\n                0.0f,\n                3.0f);\n        for (int f = 0; f < 30; ++f)\n        {\n            const bool inRange = valid && f >= activeStart && f <= activeEnd;\n            const ImVec2 a(origin.x + f * 18, origin.y + 170);\n            draw->AddRectFilled(a,\n                ImVec2(a.x + 16, a.y + 15),\n                inRange ? IM_COL32(210, 115, 70, 255)\n                        : IM_COL32(60, 75, 95, 255));\n            if (f == currentFrame)\n                draw->AddRect(a,\n                    ImVec2(a.x + 16, a.y + 15),\n                    IM_COL32(255, 235, 160, 255),\n                    0.0f,\n                    2.0f);\n        }\n        ImGui::TextUnformatted(\n            \"Display only: collision and damage processing belong to the game.\");\n    }","id":"engine-hit-window-section-3","capture":{"guide_id":"engine-hit-window","section_index":2,"scene":"engine-workshop-engine-hit-window-base","mode":"direct","caption":"下の帯が0〜29フレームで、オレンジの部分が有効区間です。現在フレームが区間内にあると、キャラクターの横に赤い枠が出ます。","backend":"DirectX 11 / WARP","code_sha256":"54688f1d1b8f65c80c209369cb78ae4d7c82d2554d696036bccd77aaa3ff7f38","image_sha256":"6b3b4ce1289ed2b5beb8a209692ebd020d3a91f528f4a8478c530ed235f7a1bd","fixture":"","initialization":""}},{"title":"うまく動かないときは","paragraphs":[],"bullets":["1回の更新で7から13へ飛んだ場合、現在フレームだけの判定では区間を通り過ぎます。固定更新や、通過した区間の検査が必要です。","再生位置を手で戻す操作と、実ゲームの攻撃の進行は同じではありません。巻き戻しでダメージを再発生させるかも決めましょう。","ヒットした相手のIDを攻撃ごとに記録すると、毎更新の多重ヒットを防ぐ設計へ発展できます。"],"id":"engine-hit-window-section-4"}],"related_guides":["engine-fixed-update","sequencer-event-track","debug-world-overlay"],"related_api":["ImGui::SliderInt","ImGui::GetWindowDrawList"],"libraries":[],"sources":[{"title":"v1.93.0：使うAPIの宣言とコメント","url":"https://github.com/ocornut/imgui/blob/c1aaac65e896a45f81f47a4d68f9959e0f86c859/imgui.h"},{"title":"公式デモ：部品の組み合わせ例","url":"https://github.com/ocornut/imgui/blob/c1aaac65e896a45f81f47a4d68f9959e0f86c859/imgui_demo.cpp"}],"capture_suite":"engine-workshop","image":"guide-engine-workbench","image_scene":"engine-workshop-engine-hit-window-base","image_caption":""},{"id":"engine-command-palette","title":"操作名で探せる、コマンドパレットを作ろう","summary":"メニューの場所を覚えていなくても操作を見つけたい。操作名を検索し、選んだ処理を実行する小さなパレットです。","category":"engine","level":"intermediate","minutes":8,"tags":["作って覚える","エディター"],"sections":[{"title":"どんな道具を作る？","paragraphs":["Find actionから検索欄を開き、Toggle gridを選ぶと背景のグリッドが切り替わります。Save sceneでは保存要求の回数が増えます。"],"preview_scene":"engine-workshop-engine-command-palette-base","preview_caption":false,"id":"engine-command-palette-section-1"},{"title":"仕組みをつかもう","paragraphs":["コマンドパレットは、ログを出すコンソールではなく、実行できる操作を探す一覧です。操作のID・表示名・実行処理を対応させておくと、メニューやショートカットと共通化できます。","この最小例は2操作だけを配列から検索し、部分一致で表示します。保存は要求回数を増やすだけで、ファイルは書きません。"],"id":"engine-command-palette-section-2"},{"title":"小さなコードで試してみよう","paragraphs":["Dear ImGuiが表示できるC++17以降のプロジェクトで、次のコードを1つの.cppへ置きます。Begin()/End()の内側からDrawWorkshop()を毎フレーム呼んでください。","Find actionを押してgridと入力します。この例の検索は大文字・小文字を区別します。空欄に戻すと両方の操作が出ます。"],"code":"#include \"imgui.h\"\n#include <cstring>\n\n    static bool gridVisible = true;\n    static int saveRequests = 0;\n    static char query[64] = \"\";\n    static const char* lastAction = \"None\";\n\n    void DrawWorkshop()\n    {\n        if (ImGui::Button(\"Find action\"))\n        {\n            query[0] = 0;\n            ImGui::OpenPopup(\"Command palette\");\n        }\n        if (ImGui::BeginPopup(\"Command palette\"))\n        {\n            ImGui::InputTextWithHint(\n                \"##search\", \"Search (case-sensitive)\", query, sizeof(query));\n            const char* names[] = {\"Toggle grid\", \"Save scene\"};\n            for (int i = 0; i < 2; ++i)\n                if (query[0] == 0 || std::strstr(names[i], query))\n                    if (ImGui::Selectable(names[i]))\n                    {\n                        if (i == 0)\n                            gridVisible = !gridVisible;\n                        else\n                            ++saveRequests;\n                        lastAction = names[i];\n                    }\n            ImGui::EndPopup();\n        }\n        ImGui::Text(\n            \"Last action: %s / save requests: %d\", lastAction, saveRequests);\n        const ImVec2 origin = ImGui::GetCursorScreenPos();\n        ImGui::Dummy(ImVec2(500, 200));\n        auto* draw = ImGui::GetWindowDrawList();\n        draw->AddRectFilled(origin,\n            ImVec2(origin.x + 500, origin.y + 200),\n            IM_COL32(30, 40, 55, 255));\n        if (gridVisible)\n            for (int x = 0; x <= 500; x += 25)\n                draw->AddLine(ImVec2(origin.x + x, origin.y),\n                    ImVec2(origin.x + x, origin.y + 200),\n                    IM_COL32(65, 90, 110, 255));\n        if (gridVisible)\n            for (int y = 0; y <= 200; y += 25)\n                draw->AddLine(ImVec2(origin.x, origin.y + y),\n                    ImVec2(origin.x + 500, origin.y + y),\n                    IM_COL32(65, 90, 110, 255));\n    }","id":"engine-command-palette-section-3","capture":{"guide_id":"engine-command-palette","section_index":2,"scene":"engine-workshop-engine-command-palette-base","mode":"direct","caption":"Find actionから、登録された操作を探すパレットを開いた状態です。","backend":"DirectX 11 / WARP","code_sha256":"384574b1b19a72318531fd276e719c2696fa82128ce4bb90f77913e722e715aa","image_sha256":"53898c198d2f360c7a368c3cb8c217c6050cff41ce163d330344ebe492f110d7","fixture":"","initialization":""}},{"title":"うまく動かないときは","paragraphs":[],"bullets":["入力した文字列をそのままコードとして実行せず、登録済みの操作へ対応させます。","選択中の物が必要な操作は、実行直前にも対象が有効か検査しましょう。","日本語や表記ゆれに対応する検索は、この例のstrstrとは別に正規化や読み情報を用意します。"],"id":"engine-command-palette-section-4"}],"related_guides":["debug-command-console","basics-keyboard-nav","engine-input-focus"],"related_api":["ImGui::InputTextWithHint","ImGui::BeginPopup","ImGui::Selectable"],"libraries":[],"sources":[{"title":"v1.93.0：使うAPIの宣言とコメント","url":"https://github.com/ocornut/imgui/blob/c1aaac65e896a45f81f47a4d68f9959e0f86c859/imgui.h"},{"title":"公式デモ：部品の組み合わせ例","url":"https://github.com/ocornut/imgui/blob/c1aaac65e896a45f81f47a4d68f9959e0f86c859/imgui_demo.cpp"}],"capture_suite":"engine-workshop","image":"guide-engine-workbench","image_scene":"engine-workshop-engine-command-palette-base","image_caption":""},{"id":"engine-scene-validation","title":"壊れた参照を、シーン全体から見つけよう","summary":"起動してからエラーを探す前に、シーンのデータをまとめて点検します。問題を選んで、その物をInspectorへ出す流れを作ります。","category":"engine","level":"intermediate","minutes":8,"tags":["作って覚える","エディター"],"sections":[{"title":"どんな道具を作る？","paragraphs":["Validate sceneで、重複IDと存在しないMesh参照を一覧にします。項目を選ぶと、どの物を調べるかが下に出ます。"],"preview_scene":"engine-workshop-engine-scene-validation-base","preview_caption":false,"id":"engine-scene-validation-section-1"},{"title":"仕組みをつかもう","paragraphs":["エラー文字列だけでなく「どの対象の問題か」も記録します。画面に表示する順番と実体を分けておくと、クリックから対象へ移動できます。","この例は固定した小さな配列を使うため行番号で結びます。実エンジンでは、検査後に並び替え・削除が起きても追えるよう、安定したIDやハンドルを持たせます。"],"id":"engine-scene-validation-section-2"},{"title":"小さなコードで試してみよう","paragraphs":["Dear ImGuiが表示できるC++17以降のプロジェクトで、次のコードを1つの.cppへ置きます。Begin()/End()の内側からDrawWorkshop()を毎フレーム呼んでください。","Validate sceneの後、Fix duplicate IDを押すと重複だけ直り、Mesh参照の問題は残ります。自動修正できる範囲を絞った例です。"],"code":"#include \"imgui.h\"\n#include <vector>\n#include <set>\n#include <string>\n\n    struct Entity\n    {\n        int id;\n        const char* name;\n        int mesh;\n    };\n    struct Issue\n    {\n        int row;\n        std::string message;\n    };\n    static std::vector<Entity> entities{\n        {101, \"Player\", 1}, {101, \"Enemy\", 1}, {205, \"Prop\", 99}};\n    static std::vector<Issue> issues;\n    static int selectedRow = -1;\n\n    void Validate()\n    {\n        issues.clear();\n        std::set<int> ids;\n        for (int i = 0; i < int(entities.size()); ++i)\n        {\n            if (!ids.insert(entities[i].id).second)\n                issues.push_back({i, \"Duplicate entity ID\"});\n            if (entities[i].mesh != 1)\n                issues.push_back({i, \"Mesh reference not found\"});\n        }\n    }\n\n    void DrawWorkshop()\n    {\n        if (ImGui::Button(\"Validate scene\"))\n            Validate();\n        ImGui::SameLine();\n        if (ImGui::Button(\"Fix duplicate ID\"))\n        {\n            entities[1].id = 102;\n            Validate();\n        }\n        ImGui::Text(\"Issues: %zu\", issues.size());\n        for (int i = 0; i < int(issues.size()); ++i)\n        {\n            ImGui::PushID(i);\n            const std::string label =\n                std::string(entities[issues[i].row].name) + \": \" +\n                issues[i].message;\n            if (ImGui::Selectable(label.c_str(), selectedRow == issues[i].row))\n                selectedRow = issues[i].row;\n            ImGui::PopID();\n        }\n        if (selectedRow >= 0)\n            ImGui::Text(\"Inspect: %s\", entities[selectedRow].name);\n        ImGui::TextUnformatted(\"This sample checks IDs and mesh IDs only.\");\n    }","id":"engine-scene-validation-section-3","capture":{"guide_id":"engine-scene-validation","section_index":2,"scene":"engine-workshop-engine-scene-validation-base","mode":"direct","caption":"Validate sceneを実際に押した結果。重複IDと見つからないMesh参照を一覧にしています。","backend":"DirectX 11 / WARP","code_sha256":"1c92c44255f404ecface71abcab7116db5f5edca3435189c5f517d574fc073fc","image_sha256":"a2c44fd2a3f7ead6193cada66158271650fcc7af4ebb1e7008dd04fa0443cf9d","fixture":"","initialization":""}},{"title":"うまく動かないときは","paragraphs":[],"bullets":["一覧をクリックする前に対象が削除されているかもしれません。移動する直前に対象の有効性を確認します。","画面を作るたびに重い全体検査を走らせず、ボタンやデータの変更をきっかけに実行します。","この例の有効なMesh IDは1だけです。実アプリではアセット台帳へ問い合わせます。"],"id":"engine-scene-validation-section-4"}],"related_guides":["debug-entity-diagnostics","engine-asset-references","engine-safe-deletion"],"related_api":["ImGui::Selectable","ImGui::PushID","ImGui::Button"],"libraries":[],"sources":[{"title":"v1.93.0：使うAPIの宣言とコメント","url":"https://github.com/ocornut/imgui/blob/c1aaac65e896a45f81f47a4d68f9959e0f86c859/imgui.h"},{"title":"公式デモ：部品の組み合わせ例","url":"https://github.com/ocornut/imgui/blob/c1aaac65e896a45f81f47a4d68f9959e0f86c859/imgui_demo.cpp"}],"capture_suite":"engine-workshop","image":"guide-engine-workbench","image_scene":"engine-workshop-engine-scene-validation-base","image_caption":""}]);
